"System: Tu es un assistant qui trie les emails professionnels d'une entreprise de menuiserie/ébénisterie (EBANISTA). Pour chaque email, réponds UNIQUEMENT en JSON avec cette structure exacte :\\n{\\n  \\"categorie\\": \\"offre_fournisseur\\" | \\"confirmation_commande\\" | \\"prospects\\" | \\"suivi_client\\" | \\"administratif\\" | \\"litige\\" | \\"facturation\\" | \\"spam\\",\\n  \\"urgent\\": true ou false,\\n  \\"resume\\": \\"résumé en 2-3 lignes maximum\\",\\n  \\"auto_envoi_possible\\": true ou false\\n}\\n\\nCatégories (avec exemples) :\\n- offre_fournisseur : devis, propositions commerciales ou catalogues reçus d'un fournisseur. Ex : \\"Devis panneaux MDF - validité 30 jours\\"\\n- confirmation_commande : accusés de réception ou confirmations d'une commande déjà passée à un fournisseur. Ex : \\"Confirmation de votre commande n°4521\\"\\n- prospects : demandes d'information ou de devis de particuliers/entreprises intéressés par nos services. Ex : \\"Devis pour cuisine sur mesure\\"\\n- suivi_client : échanges avec des clients déjà engagés sur un projet en cours. Ex : \\"Où en est mon meuble ?\\"\\n- administratif : courriers officiels, banque, assurance, impôts, RH. Ex : \\"Relevé bancaire disponible\\"\\n- litige : réclamation, mise en demeure, mention d'avocat/tribunal, forte insatisfaction client. TOUJOURS urgent=true et auto_envoi_possible=false.\\n- facturation : factures reçues ou envoyées, relances de paiement. Ex : \\"Facture n°2026-045\\"\\n- spam : newsletters, publicités, phishing évident, démarchage commercial non sollicité sans rapport avec l'activité.\\n\\nRègles d'urgence :\\n- Ne pas se fier au mot \\"urgent\\" dans le sujet s'il n'est pas justifié par le contenu réel (une simple question commerciale n'est pas urgente même si le sujet dit \\"urgent\\").\\n- Est urgent : litige (toujours), délai serré explicite (\\"réponse avant demain\\"), problème bloquant sur un chantier en cours, client insatisfait qui réclame.\\n\\nRègles auto_envoi_possible :\\n- true UNIQUEMENT pour : accusé de réception simple sans action requise, confirmation de rdv déjà validée, confirmation_commande (accusé fournisseur).\\n- false pour tout le reste, en particulier : offre_fournisseur, devis, facture, litige, toute demande nécessitant une réponse personnalisée ou une décision métier.\\n\\nLe résumé doit être factuel et concis, sans reformuler tout l'email.\\nHuman: Voici un email à analyser :\\nExpéditeur : \\"Valentin Caufriez\\" <caufriez.valentin@gmail.com>\\nSujet : Facture test 2026\\nContenu : Bonjour,\\n\\nVous trouverez ci-joint la facture concernant le chantier n°2345.\\n\\nCette facture a été soldée le 30/03/26.\\n\\nBien cordialement,\\n\\n*Caufriez Valentin*\\n\\n",{"lc":1,"type":"293","id":"294"},"claude-sonnet-4-6","https://api.anthropic.com",{},{"fetchOptions":"295"},{"lc":1,"type":"293","id":"296"},{"partId":"297","binaryFieldName":"298","expectedSize":1054232,"contentType":"264","encoding":"299","disposition":"300","filename":"267"},"filesystem-v2:workflows/FqdcdqnhtYVRYTz6/executions/318/binary_data/524ef999-f9d1-46e4-84bc-966be1317e4b","caufriez.valentin@gmail.com","PIPELINING","SIZE","ETRN","ENHANCEDSTATUSCODES","8BITMIME","DSN","AUTH PLAIN LOGIN","v.caufriez@ebanista.fr",["280"],{"address":"288","name":"301"},{"address":"280","name":"301"},["302"],"secret",["303"],{},["303"],"2","attachment_0","base64","attachment","Valentin Caufriez",{"text":"208"},"ANTHROPIC_API_KEY"]	af0c282a-7e9d-4108-bb76-ea1001f21dd8
382	{"id":"wNqeTKj68eF0lqFJ","name":"Assistant e-mails Telegram","nodes":[{"parameters":{"multipleMethods":false,"httpMethod":"POST","path":"assistant-mails-0e623b6c920aa52f22bb7772","authentication":"headerAuth","responseMode":"lastNode","responseData":"firstEntryJson","options":{}},"type":"n8n-nodes-base.webhook","typeVersion":2,"position":[0,0],"id":"38d82a0d-76d5-43d9-ae45-75b462b94e8f","name":"Webhook Telegram","credentials":{"httpHeaderAuth":{"id":"86dpp3Vg9wZOdnpT","name":"Pont Telegram (secret)"}},"webhookId":"f8f6f913-721c-4166-8653-5172dca9442e"},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"// Réception d'une mise à jour Telegram : filtre l'expéditeur, évite les doublons, retrouve la conversation en cours\\nconst ALLOWED = 8848139246;\\nconst upd = $input.first().json.body || {};\\nconst sd = $getWorkflowStaticData('global');\\nsd.seen = sd.seen || [];\\nsd.sessions = sd.sessions || {};\\n\\nconst msg = upd.message, cb = upd.callback_query;\\nconst from = (msg && msg.from) || (cb && cb.from) || {};\\nconst chat = (msg && msg.chat) || (cb && cb.message && cb.message.chat) || {};\\n\\n// seul le compte de Valentin est autorisé : tout autre expéditeur est ignoré sans réponse\\nif (Number(from.id) !== ALLOWED || Number(chat.id) !== ALLOWED) return [{ json: { route: 'ignore' } }];\\n\\n// une même mise à jour n'est jamais traitée deux fois\\nif (upd.update_id !== undefined) {\\n  if (sd.seen.includes(upd.update_id)) return [{ json: { route: 'ignore' } }];\\n  sd.seen.push(upd.update_id);\\n  if (sd.seen.length > 100) sd.seen = sd.seen.slice(-100);\\n}\\n\\nconst key = String(chat.id);\\nlet s = sd.sessions[key];\\nif (s && Date.now() - (s.updated || 0) > 45 * 60 * 1000) { delete sd.sessions[key]; s = undefined; } // conversation expirée après 45 min\\n\\nlet route = 'message', text = '', pick = 0;\\nif (cb) route = 'callback';\\nelse if (msg && msg.text && s && s.state === 'reply_pick' && s.mail_candidates && /^\\\\s*[1-9]\\\\s*$/.test(msg.text)) { route = 'reply_choose'; pick = Number(msg.text.trim()); }\\nelse if (msg && msg.text) route = 'claude';\\nelse text = \\"Je ne sais traiter que du texte pour l'instant. Écrivez-moi (ou dictez avec le clavier de votre téléphone) à qui écrire, le sujet et ce qu'il faut dire.\\";\\n\\nreturn [{ json: {\\n  route, text, pick, chat_id: chat.id, update_id: upd.update_id,\\n  user_text: msg ? (msg.text || '') : '',\\n  cb_data: cb ? (cb.data || '') : '', cb_id: cb ? cb.id : '',\\n  session: s || null,\\n} }];\\n","notice":""},"type":"n8n-nodes-base.code","typeVersion":2,"position":[250,0],"id":"a68b15ff-53c4-461b-bd58-41dd16e9205d","name":"Normaliser la mise à jour"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"e5f150b9-ca79-4b8e-a4de-31f93b51986d","leftValue":"={{ $json.route }}","rightValue":"callback","operator":{"type":"string","operation":"equals"}}],"combinator":"and"},"looseTypeValidation":false,"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[500,0],"id":"b97cb587-21e9-421d-9430-9084ae3b142f","name":"Bouton ?"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"b7888c90-e124-44fd-9e09-fc064122c1a0","leftValue":"={{ $json.route }}","rightValue":"claude","operator":{"type":"string","operation":"equals"}}],"combinator":"and"},"looseTypeValidation":false,"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[500,400],"id":"9d553bda-d232-444a-9640-de80e4657d13","name":"Demande à Claude ?"},{"parameters":{"resource":"message","operation":"sendMessage","chatId":"={{ $json.chat_id }}","text":"={{ $json.text }}","replyMarkup":"none","additionalFields":{"appendAttribution":false}},"type":"n8n-nodes-base.telegram","typeVersion":1.2,"position":[2400,400],"id":"19ae550c-4046-4f06-8953-95bd151c949c","name":"Message texte","credentials":{"telegramApi