.to_name) + ' ' : ''}<${t.to}>`,\\n  `Subject: ${encodeHeader(t.subject)}`,\\n  `Date: ${new Date().toUTCString().replace('GMT', '+0000')}`,\\n  `Message-ID: ${msgId}`,\\n  ...(t.in_reply_to ? [`In-Reply-To: ${t.in_reply_to}`, `References: ${t.in_reply_to}`] : []),\\n  'MIME-Version: 1.0',\\n  'Content-Type: text/plain; charset=UTF-8',\\n  'Content-Transfer-Encoding: base64',\\n];\\nconst body = b64(t.text.replace(/\\\\r?\\\\n/g, CRLF)).replace(/(.{76})/g, '$1' + CRLF);\\nreturn [{ json: { rfc822: headers.join(CRLF) + CRLF + CRLF + body + CRLF } }];\\n","notice":""},"type":"n8n-nodes-base.code","typeVersion":2,"position":[1900,-200],"id":"f6923a95-bb7b-4c31-9f01-ce319988c6b8","name":"Composer la copie v"},{"parameters":{"authentication":"coreImapAccount","resource":"email","operation":"createDraft","destinationMailbox":{"__rl":true,"mode":"path","value":"Sent"},"inputFormat":"rfc822","rfc822":"={{ $json.rfc822 }}"},"type":"n8n-nodes-imap.imap","typeVersion":1,"position":[2000,-200],"id":"d406e9e9-392e-4a94-8369-def542294b66","name":"Enregistrer la copie v","credentials":{"imap":{"id":"wVKdbE1JQnIB1kzf","name":"IMAP - v.caufriez@ebanista.fr"}},"onError":"continueRegularOutput"},{"parameters":{"authentication":"coreImapAccount","resource":"email","operation":"setEmailFlags","mailboxPath":{"__rl":true,"mode":"path","value":"Sent"},"emailUid":"={{ $json.uid }}","flags":{"\\\\Draft":false,"\\\\Seen":true}},"type":"n8n-nodes-imap.imap","typeVersion":1,"position":[2100,-200],"id":"2feedd86-abe5-4484-bc9c-cc86dff6e8a4","name":"Marquer la copie lue v","credentials":{"imap":{"id":"wVKdbE1JQnIB1kzf","name":"IMAP - v.caufriez@ebanista.fr"}},"onError":"continueRegularOutput"},{"parameters":{"resource":"email","operation":"send","fromEmail":"={{ $json.from_header }}","toEmail":"={{ $json.to }}","subject":"={{ $json.subject }}","emailFormat":"text","text":"={{ $json.text }}","options":{"appendAttribution":false}},"type":"n8n-nodes-base.emailSend","typeVersion":2.1,"position":[1700,50],"id":"f5d96369-7c17-4079-82bd-fde6f7028262","name":"Envoi depuis contact@ebanista.fr","credentials":{"smtp":{"id":"4znohlVNgQDzDtyl","name":"SMTP - contact@ebanista.fr"}},"onError":"continueErrorOutput","webhookId":"b7a0393a-32b1-4499-ba32-4e25112b52c4"},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"// Compose la copie du mail envoyé (RFC822) pour le dossier Envoyés de la boîte\\nconst t = $('Traiter le bouton').first().json;\\nconst info = $input.first().json;\\nconst CRLF = '\\\\r\\\\n';\\nconst b64 = (s) => Buffer.from(s, 'utf8').toString('base64');\\nconst isAscii = (s) => /^[\\\\x20-\\\\x7e]*$/.test(s);\\nconst encodeHeader = (s) => {\\n  if (isAscii(s)) return s;\\n  const chars = Array.from(s), parts = [];\\n  for (let i = 0; i < chars.length; i += 10) parts.push(`=?UTF-8?B?${b64(chars.slice(i, i + 10).join(''))}?=`);\\n  return parts.join(CRLF + ' ');\\n};\\nconst name = (n) => !n ? '' : (!isAscii(n) ? `=?UTF-8?B?${b64(n)}?=` : (/[^\\\\w .'-]/.test(n) ? `\\"${n.replace(/([\\"\\\\\\\\])/g, '\\\\\\\\$1')}\\"` : n));\\nconst msgId = info.messageId || `<copie-${Date.now()}@ebanista.fr>`;\\nconst headers = [\\n  `From: ${name(t.fromName)} <${t.from}>`,\\n  `To: ${t.to_name ? name(t.to_name) + ' ' : ''}<${t.to}>`,\\n  `Subject: ${encodeHeader(t.subject)}`,\\n  `Date: ${new Date().toUTCString().replace('GMT', '+0000')}`,\\n  `Message-ID: ${msgId}`,\\n  ...(t.in_reply_to ? [`In-Reply-To: ${t.in_reply_to}`, `References: ${t.in_reply_to}`] : []),\\n  'MIME-Version: 1.0',\\n  'Content-Type: text/plain; charset=UTF-8',\\n  'Content-Transfer-Encoding: base64',\\n];\\nconst body = b64(t.text.replace(/\\\\r?\\\\n/g, CRLF)).replace(/(.{76})/g, '$1' + CRLF);\\nreturn [{ json: { rfc822: headers.join(CRLF) + CRLF + CRLF + body + CRLF } }];\\n","notice":""},"type":"n8n-nodes-base.code","typeVersion":2,"position":[1900,50],"id":"fd5c6213-656e-4efd-a90d-b697bca98d94","name":"Composer la copie c"},{"parameters":{"authentication":"coreImapAccount","resource":"email","operation":"createDraft","destinationMailbox":{"__rl":true,"mode":"path","value":"Sent"},"inputFormat":"rfc822","rfc822":"={{ $json.rfc822 }}"},"type":"n8n-nodes-imap.imap","typeVersion":1,"position":[2000,50],"id":"4ea25f22-035a-4d4f-99bd-8ca420325361","name":"Enregistrer la copie c","credentials":{"imap":{"id":"nFnyy1qJ60BZTKsw","name":"IMAP - contact@ebanista.fr"}},"onError":"continueRegularOutput"},{"parameters":{"authentication":"coreImapAccount","resource":"email","operation":"setEmailFlags","mailboxPath":{"__rl":true,"mode":"path","value":"Sent"},"emailUid":"={{ $json.uid }}","flags":{"\\\\Draft":false,"\\\\Seen":true}},"type":"n8n-nodes-imap.imap","typeVersion":1,"position":[2100,50],"id":"dc4f64a6-1ce2-48a9-a6f4-9f9c07f8b033","name":"Marquer la copie lue c","credentials":{"imap":{"id":"nFnyy1qJ60BZTKsw","name":"IMAP - contact@ebanista.fr"}},"onError":"continueRegularOutput"},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"// Construit le message envoyé à Claude : demande de Valentin + brouillon en cours + adresses proposées + éventuel mail reçu auquel répondre\\nconst j = $input.first().json;\\nconst s = j.session;\\nconst parts = ['MESSAGE DE VALENTIN :', j.user_text];\\nif (s && s.reply_to) {\\n  const r = s.reply_to;\\n  parts.push('', 'MAIL REÇU AUQUEL TU RÉPONDS :',\\n    `De : ${r.from_name ? r.from_name + ' ' : ''}<${r.from_address}>`,\\n    `Objet : ${r.subject}`, `Reçu le : ${r.recu_le}`, `Boîte de réception : ${r.boite}`,\\n    'Contenu :', r.extrait || '(vide)');\\n  if (r.boite === 'contact') {\\n    parts.push('', \\"STYLE POUR CETTE BOÎTE (administrative) : vouvoiement soigné, phrases complètes et courtoises, \\\\\\"Merci d'avance pour votre retour.\\\\\\" avant la formule de fin (\\\\\\"Cordialement,\\\\\\"), aucune familiarité. Écris au nom de l'entreprise (« nous »), pas à la première personne du singulier.\\");\\n  }\\n}\\nif (s && s.draft && s.draft.body) {\\n  const d = s.draft;\\n  parts.push('', 'BROUILLON EN COURS :', `À : ${d.to_name || ''} <${d.to_address || 'adresse inconnue'}>`, `Objet : ${d.subject || ''}`, 'Corps :', d.body);\\n}\\nif (s && s.candidates && s.candidates.length) {\\n  parts.push('', 'ADRESSES PROPOSÉES POUR LE DESTINATAIRE (il peut répondre par un numéro) :');\\n  s.candidates.forEach((c, i) => parts.push(`${i + 1}) ${c.name ? c.name + ' ' : ''}<${c.address}>`));\\n}\\nreturn [{ json: { ...j, prompt: parts.join('\\\\n') } }];\\n","notice":""},"type":"n8n-nodes-base.code","typeVersion":2,"position":[750,400],"id":"f34ae230-636d-4656-b764-1c9d146f83c8","name":"Préparer l'appel Claude"},{"parameters":{"notice":"","promptType":"define","text":"={{ $json.prompt }}","hasOutputParser":false,"needsFallback":false,"messages":{"messageValues":[{"type":"SystemMessagePromptTemplate","message":"Tu es l'assistant de rédaction d'e-mails de Valentin Caufriez, gérant d'EBANISTA (menuiserie / ébénisterie sur mesure). Valentin te dicte par Telegram, en langage courant, un e-mail à envoyer (destinataire, sujet, contenu). Tu rédiges l'e-mail à sa place, dans son style ; ensuite il choisit la boîte d'envoi et valide.\\n\\nTu reçois son message, et éventuellement le brouillon en cours (à réviser) et une liste numérotée d'adresses proposées.\\n\\nRéponds UNIQUEMENT par un objet JSON, sans texte autour :\\n{\\n  \\"intent\\": \\"draft\\" | \\"revise\\" | \\"reply\\" | \\"cancel\\" | \\"other\\",\\n  \\"to_name\\": \\"nom du destinataire\\" ou null,\\n  \\"to_address\\": \\"adresse e-mail\\" ou null,\\n  \\"subject\\": \\"objet\\" ou null,\\n  \\"body\\": \\"corps complet du mail, formule de politesse comprise, SANS signature\\" ou null,\\n  \\"reply\\": \\"message court à afficher à Valentin\\" ou null,\\n  \\"find\\": {\\"sender\\": \\"expéditeur, société ou personne cité(e)\\" ou null, \\"subject\\": \\"mots du sujet cités\\" ou null, \\"box\\": \\"v.caufriez\\" | \\"contact\\" | null} ou null,\\n  \\"instructions\\": \\"ce que Valentin veut dire dans la réponse\\" ou null\\n}\\n\\nINTENTIONS :\\n- \\"draft\\" : nouvelle demande d'e-mail.\\n- \\"revise\\" : il modifie le brouillon en cours (ajoute, retire, raccourcit, change le ton, corrige un détail). Change uniquement ce qui est demandé, garde le reste, et renvoie le mail complet à jour.\\n- \\"reply\\" : il demande de RÉPONDRE à un mail déjà reçu (« réponds au mail de Dispano sur le devis », « réponds à Mme Martin », « réponds au dernier mail de contact »). Renseigne \\"find\\" (qui a écrit, mots du sujet, boîte si précisée) et \\"instructions\\" (ce qu'il veut dire dans la réponse, ou null s'il ne dit rien). Ne rédige PAS la réponse à ce stade : \\"body\\" reste null. Aucune adresse n'est nécessaire.\\n- \\"cancel\\" : il abandonne ce brouillon.\\n- Dans le champ \\"reply\\", vouvoie toujours Valentin.\\n- \\"other\\" : ce n'est pas une demande de mail (question, remerciement, message flou). Réponds brièvement dans \\"reply\\" et explique au besoin comment demander un mail : à qui, quel sujet, ce qu'il faut dire.\\n\\nDESTINATAIRE :\\n- to_address : seulement si une adresse figure dans son message ou dans le brouillon en cours, ou s'il choisit un numéro dans la liste d'adresses proposées. N'invente JAMAIS une adresse e-mail. Sinon null (avec to_name si tu as un nom).\\n- Si l'objet n'est pas dicté, propose un objet court et pertinent.\\n\\nRÉPONSE À UN MAIL REÇU :\\n- Si le message contient un bloc \\"MAIL REÇU AUQUEL TU RÉPONDS\\", rédige la réponse à ce mail : intent \\"draft\\" (ou \\"revise\\" si un brouillon existe déjà), et renvoie seulement le corps de la réponse dans \\"body\\". to_address, to_name et subject seront remplis automatiquement : mets-les à null.\\n- Réponds précisément à ce que dit le mail reçu, en suivant les instructions de Valentin. Ne cite pas le mail reçu (il sera cité automatiquement). Applique les mêmes règles d'invention et de style.\\n\\nSTYLE DU CORPS (celui de Valentin) :\\n- Court et direct, 3 à 8 lignes en général, paragraphes très courts, aucune formule ampoulée.\\n- Vouvoiement par défaut ; tutoiement (\\"Salut Prénom,\\") seulement s'il le demande ou indique que le destinataire est un proche ou un fournisseur habituel.\\n- COHÉRENCE : choisis une seule forme (vouvoiement OU tutoiement) et garde-la dans tout le mail, salutation et formule de politesse comprises. Ne mélange jamais \\"vous\\" et \\"tu\\", ni \\"Bonjour,\\" avec du tutoiement.\\n- Salutation : \\"Bonjour,\\" ou \\"Bonjour Prénom,\\" ; \\"Salut Prénom,\\" en tutoiement.\\n- Commandes et demandes de prix : liste à tirets, une quantité ou une référence par ligne.\\n- Termine par une formule de politesse seule : \\"Cordialement,\\" (ou \\"À bientôt,\\" / \\"Bien à toi,\\" en tutoiement). Ne mets AUCUN nom ni signature après : la signature est ajoutée automatiquement.\\n\\nRÈGLES STRICTES :\\n- N'invente JAMAIS un prix, un délai, une date, une quantité, une référence, une dimension ni un engagement qu'il n'a pas dicté. S'il manque une information indispensable, écris [À COMPLÉTER : ce qu'il faut préciser] à l'endroit voulu.\\n- Ne mets pas l'objet dans le corps. N'ajoute ni commentaire, ni \\"Voici le mail\\".\\n- Écris en français, sauf si Valentin demande une autre langue."}]},"batching":{}},"type":"@n8n/n8n-nodes-langchain.chainLlm","typeVersion":1.9,"position":[1000,400],"id":"1b7a41c4-06c6-4dcf-b42d-f5b04dd8c3c3","name":"Rédiger avec Claude"},{"parameters":{"notice":"","model":{"__rl":true,"mode":"list","value":"claude-sonnet-4-6","cachedResultName":"Claude Sonnet 4.6"},"options":{"temperature":0.3}},"type":"@n8n/n8n-nodes-langchain.lmChatAnthropic","typeVersion":1.5,"position":[1040,620],"id":"82cde0b7-3eed-4754-a336-679f4003e3ed","name":"Modèle Claude (assistant)","credentials":{"anthropicApi":{"id":"FRxZizEr7zCaHHZp","name":"Claude API"}}},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"// Applique la réponse de Claude à la conversation (brouillon, réponse à un mail, annulation, question) et décide de la suite\\nconst j = $('Normaliser la mise à jour').first().json;\\nconst raw = String($input.first().json.text || '');\\nlet out = null;\\ntry { out = JSON.parse(raw.match(/\\\\{[\\\\s\\\\S]*\\\\}/)[0]); } catch (e) { out = null; }\\n\\nconst sd = $getWorkflowStaticData('global');\\nsd.sessions = sd.sessions || {};\\nconst key = String(j.chat_id);\\nconst prev = sd.sessions[key];\\nconst say = (text) => [{ json: { chat_id: j.chat_id, text, next: 'message' } }];\\nconst reSubject = (s) => 'Re: ' + String(s || '').replace(/^\\\\s*((re|ré)\\\\s*:\\\\s*)+/i, '').trim();\\n\\nif (!out) return say(\\"Je n'ai pas bien compris. Pouvez-vous reformuler votre demande ?\\");\\nif (out.intent === 'cancel') { delete sd.sessions[key]; return say('Brouillon annulé.'); }\\nif (out.intent === 'other') return say(out.reply || \\"Dites-moi à qui écrire, le sujet et ce qu'il faut dire (ou « réponds au mail de … »), et je prépare le mail.\\");\\n\\n// demande de réponse à un mail déjà reçu : on retrouve d'abord le mail dans le registre\\nif (out.intent === 'reply') {\\n  sd.sessions[key] = { state: 'reply_search', find: out.find || {}, instructions: out.instructions || '', updated: Date.now() };\\n  return [{ json: { chat_id: j.chat_id, next: 'find' } }];\\n}\\n\\nconst okMail = (a) => (typeof a === 'string' && /^[^\\\\s@<>]+@[^\\\\s@<>]+\\\\.[^\\\\s@<>]+$/.test(a.trim())) ? a.trim() : null;\\nconst d = (prev && prev.draft) || {};\\n\\n// réponse à un mail reçu (première rédaction, ou révision d'un brouillon de réponse)\\nconst replyTo = prev && prev.reply_to;\\nif (replyTo && (prev.reply_pending || (out.intent === 'revise' && prev.draft))) {\\n  const body = out.body || d.body || null;\\n  const nd = { to_name: replyTo.from_name || null, to_address: replyTo.from_address, subject: reSubject(replyTo.subject), body };\\n  sd.sessions[key] = { state: 'draft', draft: nd, reply_to: replyTo, candidates: null, updated: Date.now() };\\n  if (!body) return say(out.reply || 'Que voulez-vous répondre ?');\\n  return [{ json: { chat_id: j.chat_id, next: 'decide', lookup_name: '' } }];\\n}\\n\\nlet nd;\\nif (out.intent === 'revise' && prev && prev.draft) {\\n  nd = {\\n    to_name: out.to_name || d.to_name || null,\\n    to_address: okMail(out.to_address) || d.to_address || null,\\n    subject: out.subject || d.subject || null,\\n    body: out.body || d.body || null,\\n  };\\n} else {\\n  nd = { to_name: out.to_name || null, to_address: okMail(out.to_address), subject: out.subject || null, body: out.body || null };\\n}\\nsd.sessions[key] = { state: 'draft', draft: nd, candidates: null, updated: Date.now() };\\n\\nif (!nd.body) return say(out.reply || 'Que voulez-vous dire dans ce mail ?');\\nconst needLookup = !nd.to_address && !!nd.to_name;\\nreturn [{ json: { chat_id: j.chat_id, next: needLookup ? 'lookup' : 'decide', lookup_name: nd.to_name || '' } }];\\n","notice":""},"type":"n8n-nodes-base.code","typeVersion":2,"position":[1250,400],"id":"d30f7bcb-c50b-4a1b-889d-129ce5a33cdf","name":"Appliquer la réponse de Claude"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"59edca37-64ac-4175-a792-784d8321aaf3","leftValue":"={{ $json.next }}","rightValue":"message","operator":{"type":"string","operation":"equals"}}],"combinator":"and"},"looseTypeValidation":false,"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[1500,400],"id":"0bb8ea51-3d39-49d5-97af-e9ec86eca95e","name":"Message direct ?"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"71940613-10d6-4f53-b9ab-d8f21dc5f7c3","leftValue":"={{ $json.next }}","rightValue":"find","operator":{"type":"string","operation":"equals"}}],"combinator":"and"},"looseTypeValidation":false,"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[1750,800],"id":"64b63e34-cbff-4e40-b768-11714307a1a4","name":"Chercher un mail ?"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"50546119-e93f-47e3-8633-8080ad4768a4","leftValue":"={{ $json.next }}","rightValue":"lookup","operator":{"type":"string","operation":"equals"}}],"combinator":"and"},"looseTypeValidation":false,"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[1750,550],"id":"2d117271-e3a9-46a3-a0ca-63c2a8a7d4c4","name":"Recherche d'adresse ?"},{"parameters":{"authentication":"coreImapAccount","resource":"email","operation":"getEmailsList","mailboxPath":{"__rl":true,"mode":"path","value":"Sent"},"emailDateRange":{"since":"={{ $now.minus({ years: 2 }).toISO() }}"},"emailFlags":{},"emailSearchFilters":{"to":"={{ ($('Appliquer la réponse de Claude').first().json.lookup_name || '').split(/\\\\s+/).filter(Boolean).sort((a, b) => b.length - a.length)[0] || 'introuvable-xyz' }}"},"limit":40,"includeParts":[]},"type":"n8n-nodes-imap.imap","typeVersion":1,"position":[2000,700],"id":"7ae1645f-2842-4d33-a6b2-f0cd5b2c8464","name":"Recherche Envoyés v.caufriez","credentials":{"imap":{"id":"wVKdbE1JQnIB1kzf","name":"IMAP - v.caufriez@ebanista.fr"}},"alwaysOutputData":true,"onError":"continueRegularOutput"},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"// Regroupe en un seul élément les résultats de la recherche dans les Envoyés de v.caufriez@\\nconst found = $input.all().map(i => i.json).filter(j => j && j.envelope && !j.error);\\nreturn [{ json: { found } }];\\n","notice":""},"type":"n8n-nodes-base.code","typeVersion":2,"position":[2200,700],"id":"71bd31fb-6b8f-4cda-a9b9-7a4f93c33e27","name":"Regrouper les résultats v.caufriez"},{"parameters":{"authentication":"coreImapAccount","resource":"email","operation":"getEmailsList","mailboxPath":{"__rl":true,"mode":"path","value":"Sent"},"emailDateRange":{"since":"={{ $now.minus({ years: 2 }).toISO() }}"},"emailFlags":{},"emailSearchFilters":{"to":"={{ ($('Appliquer la réponse de Claude').first().json.lookup_name || '').split(/\\\\s+/).filter(Boolean).sort((a, b) => b.length - a.length)[0] || 'introuvable-xyz' }}"},"limit":40,"includeParts":[]},"type":"n8n-nodes-imap.imap","typeVersion":1,"position":[2400,700],"id":"e12f0e8e-3279-4d40-94f8-980df6305019","name":"Recherche Envoyés contact","credentials":{"imap":{"id":"nFnyy1qJ60BZTKsw","name":"IMAP - contact@ebanista.fr"}},"alwaysOutputData":true,"onError":"continueRegularOutput"},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"// Retrouve l'adresse du destinataire à partir de son nom, dans les dossiers Envoyés des deux boîtes\\nconst ctx = $('Appliquer la réponse de Claude').first().json;\\nconst j = $('Normaliser la mise à jour').first().json;\\nconst sd = $getWorkflowStaticData('global');\\nconst key = String(j.chat_id);\\nconst s = sd.sessions[key];\\nconst strip = (t) => String(t || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');\\nconst tokens = strip(ctx.lookup_name).split(/[^a-z0-9]+/).filter(t => t.length >= 2);\\n\\nconst first = ($('Regrouper les résultats v.caufriez').first().json.found) || [];\\nconst second = $input.all().map(i => i.json).filter(x => x && x.envelope && !x.error);\\nconst MINE = ['v.caufriez@ebanista.fr', 'contact@ebanista.fr', 'comptabilite@ebanista.fr'];\\nconst tally = {};\\nfor (const m of [...first, ...second]) {\\n  for (const t of ((m.envelope && m.envelope.to) || [])) {\\n    const addr = String(t.address || '').toLowerCase();\\n    if (!addr || MINE.includes(addr)) continue;\\n    const hay = strip((t.name || '') + ' ' + addr);\\n    if (tokens.length && !tokens.every(tok => hay.includes(tok))) continue;\\n    const e = tally[addr] || (tally[addr] = { address: addr, name: t.name || '', count: 0 });\\n    e.count++;\\n    if (!e.name && t.name) e.name = t.name;\\n  }\\n}\\nconst list = Object.values(tally).sort((a, b) => b.count - a.count);\\nif (s) {\\n  if (list.length === 1 || (list.length > 1 && list[0].count >= 2 * list[1].count && list[0].count >= 2)) {\\n    s.draft.to_address = list[0].address;\\n    if (!s.draft.to_name && list[0].name) s.draft.to_name = list[0].name;\\n  } else if (list.length > 1) {\\n    s.candidates = list.slice(0, 5).map(c => ({ name: c.name, address: c.address }));\\n  }\\n  s.updated = Date.now();\\n}\\nreturn [{ json: { chat_id: j.chat_id } }];\\n","notice":""},"type":"n8n-nodes-base.code","typeVersion":2,"position":[2600,700],"id":"225ad25d-6ae5-4642-b2c1-68b238030d26","name":"Retrouver l'adresse"},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"// Décide ce qu'il faut répondre à Valentin : question sur l'adresse, informations manquantes, ou aperçu avec boutons\\nconst j = $('Normaliser la mise à jour').first().json;\\nconst sd = $getWorkflowStaticData('global');\\nconst key = String(j.chat_id);\\nconst s = sd.sessions[key];\\nconst out = (text, preview = false) => {\\n  const rec = s && s.reply_to ? s.reply_to.boite : '';\\n  const tag = ' (boîte du mail reçu)';\\n  return [{ json: { chat_id: j.chat_id, text, preview,\\n    label_v: '✉️ Envoyer depuis v.caufriez@ebanista.fr' + (rec === 'v.caufriez' ? tag : ''),\\n    label_c: '✉️ Envoyer depuis contact@ebanista.fr' + (rec === 'contact' ? tag : '') } }];\\n};\\nif (!s || !s.draft) return out(\\"Je n'ai plus de brouillon en cours. Redites-moi à qui écrire et ce qu'il faut dire.\\");\\nconst d = s.draft;\\n\\nif (s.candidates && s.candidates.length) {\\n  s.state = 'awaiting_address'; s.updated = Date.now();\\n  const lines = s.candidates.map((c, i) => `${i + 1}) ${c.name ? c.name + ' ' : ''}<${c.address}>`).join('\\\\n');\\n  return out(`Plusieurs adresses possibles pour « ${d.to_name || 'ce destinataire'} » :\\\\n${lines}\\\\n\\\\nRépondez par le numéro, ou donnez-moi directement l'adresse.`);\\n}\\nif (!d.to_address) {\\n  s.state = 'awaiting_address'; s.updated = Date.now();\\n  return out(`Je n'ai pas trouvé l'adresse e-mail de ${d.to_name || 'ce destinataire'}. Pouvez-vous me la donner ?`);\\n}\\nconst missing = (d.body.match(/\\\\[À COMPLÉTER[^\\\\]]*\\\\]/g) || []);\\nconst r = s.reply_to;\\nconst when = r && r.recu_le ? new Date(r.recu_le).toLocaleString('fr-FR', { timeZone: 'Europe/Paris', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }) : '';\\nconst head = r ? `↩️ Réponse au mail « ${(r.subject || '').slice(0, 80)} » reçu le ${when} sur ${r.boite}\\\\n\\\\n` : '';\\nconst draftText = `À : ${d.to_name ? d.to_name + ' ' : ''}<${d.to_address}>\\\\nObjet : ${d.subject || '(sans objet)'}\\\\n\\\\n${d.body}`;\\nif (missing.length) {\\n  s.state = 'awaiting_info'; s.updated = Date.now();\\n  return out(`Il manque des informations avant de pouvoir envoyer :\\\\n${missing.map(m => '• ' + m).join('\\\\n')}\\\\n\\\\nPrécisez-les-moi et je mets le brouillon à jour.\\\\n\\\\n— Brouillon actuel —\\\\n${head}${draftText}`);\\n}\\ns.state = 'ready'; s.updated = Date.now();\\nreturn out(`✉️ Brouillon prêt\\\\n\\\\n${head}${draftText}\\\\n\\\\n(La signature est ajoutée selon la boîte choisie${r ? ', et le mail d\\\\'origine est cité en dessous' : ''}.)\\\\nChoisissez la boîte d'envoi, ou dites-moi quoi modifier.`, true);\\n","notice":""},"type":"n8n-nodes-base.code","typeVersion":2,"position":[2800,550],"id":"a678d670-a328-4bee-9928-04a76d8ad2a1","name":"Décider du message"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"18b07251-fe88-4004-a1da-a2e871a9e612","leftValue":"={{ String($json.preview) }}","rightValue":"true","operator":{"type":"string","operation":"equals"}}],"combinator":"and"},"looseTypeValidation":false,"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[3050,550],"id":"3caff499-f787-4303-8b5c-d61ec68ac3b7","name":"Aperçu ?"},{"parameters":{"curlImport":"","method":"GET","url":"http://localhost:5678/api/v1/data-tables/xhFI6TwJikamYjPL/rows?limit=250&sortBy=recu_le%3Adesc","authentication":"genericCredentialType","genericAuthType":"httpHeaderAuth","provideSslCertificates":false,"sendQuery":false,"sendHeaders":false,"sendBody":false,"options":{},"infoMessage":""},"type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[2000,900],"id":"e8a7bb99-83c5-4b32-a2f4-2f0a027a72a8","name":"Chercher dans le registre","credentials":{"httpHeaderAuth":{"id":"Lfuh7XFXewkeDjJe","name":"n8n API Key (interne)"}}},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"// Retrouve dans le registre le mail reçu auquel Valentin veut répondre\\nconst j = $('Normaliser la mise à jour').first().json;\\nconst sd = $getWorkflowStaticData('global');\\nconst key = String(j.chat_id);\\nconst s = (sd.sessions || {})[key];\\nconst say = (text) => [{ json: { chat_id: j.chat_id, text, next: 'message' } }];\\nif (!s || s.state !== 'reply_search') return say(\\"Je n'ai plus de demande en cours. Redites-moi à quel mail répondre.\\");\\n\\nconst rows = ($input.first().json.data || []).filter(r => r && r.from_address);\\nconst f = s.find || {};\\nconst strip = (t) => String(t || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');\\nconst toks = (t) => strip(t).split(/[^a-z0-9]+/).filter(x => x.length >= 2);\\nconst st = toks(f.sender), jt = toks(f.subject);\\nconst bx = strip(f.box || '');\\nconst boxOk = (r) => !bx || (bx.includes('contact') ? r.boite === 'contact' : (bx.includes('caufriez') || bx.includes('valentin')) ? r.boite === 'v.caufriez' : true);\\n\\nlet list = rows.filter(r => {\\n  if (!boxOk(r)) return false;\\n  const who = strip((r.from_name || '') + ' ' + r.from_address);\\n  if (st.length && !st.every(t => who.includes(t))) return false;\\n  return true;\\n});\\nif (jt.length) {\\n  const what = (r) => strip((r.subject || '') + ' ' + (r.resume || ''));\\n  const strict = list.filter(r => jt.every(t => what(r).includes(t)));\\n  list = strict.length ? strict : list.filter(r => jt.some(t => what(r).includes(t)));\\n}\\nlist.sort((a, b) => String(b.recu_le).localeCompare(String(a.recu_le)));\\nconst top = list.slice(0, 5);\\n\\nconst keep = (r) => ({ boite: r.boite, recu_le: r.recu_le, from_address: r.from_address, from_name: r.from_name, subject: r.subject, message_id: r.message_id, extrait: r.extrait, resume: r.resume });\\nconst fmt = (r) => {\\n  const d = r.recu_le ? new Date(r.recu_le).toLocaleString('fr-FR', { timeZone: 'Europe/Paris', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }) : '';\\n  return `${r.from_name ? r.from_name + ' ' : ''}<${r.from_address}> — « ${(r.subject || '').slice(0, 70)} » — ${d} — boîte ${r.boite}`;\\n};\\n\\nif (top.length === 0) {\\n  delete sd.sessions[key];\\n  return say(\\"Je n'ai pas retrouvé de mail correspondant dans les 45 derniers jours (boîtes v.caufriez et contact). Précisez l'expéditeur ou un mot de l'objet.\\");\\n}\\nif (top.length > 1) {\\n  s.state = 'reply_pick'; s.mail_candidates = top.map(keep); s.updated = Date.now();\\n  return say(`Plusieurs mails correspondent :\\\\n${top.map((r, i) => `${i + 1}) ${fmt(r)}`).join('\\\\n')}\\\\n\\\\nRépondez par le numéro du mail auquel répondre.`);\\n}\\nconst chosen = keep(top[0]);\\nsd.sessions[key] = { state: 'reply_pending', reply_to: chosen, reply_pending: true, instructions: s.instructions || '', updated: Date.now() };\\nreturn [{ json: { chat_id: j.chat_id, next: 'redraft', user_text: s.instructions || 'Rédige une réponse appropriée à ce mail.', session: sd.sessions[key] } }];\\n","notice":""},"type":"n8n-nodes-base.code","typeVersion":2,"position":[2250,900],"id":"fdc80d65-55b5-4a0d-ba98-5740718c2e7e","name":"Retrouver le mail"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"2727508b-fe82-4be3-97df-9238a59f1b16","leftValue":"={{ $json.next }}","rightValue":"redraft","operator":{"type":"string","operation":"equals"}}],"combinator":"and"},"looseTypeValidation":false,"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[2500,900],"id":"63fd2add-e7ae-470c-b5d2-bcb06f453cb9","name":"Réponse à rédiger ?"},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"// Construit le message envoyé à Claude : demande de Valentin + brouillon en cours + adresses proposées + éventuel mail reçu auquel répondre\\nconst j = $input.first().json;\\nconst s = j.session;\\nconst parts = ['MESSAGE DE VALENTIN :', j.user_text];\\nif (s && s.reply_to) {\\n  const r = s.reply_to;\\n  parts.push('', 'MAIL REÇU AUQUEL TU RÉPONDS :',\\n    `De : ${r.from_name ? r.from_name + ' ' : ''}<${r.from_address}>`,\\n    `Objet : ${r.subject}`, `Reçu le : ${r.recu_le}`, `Boîte de réception : ${r.boite}`,\\n    'Contenu :', r.extrait || '(vide)');\\n  if (r.boite === 'contact') {\\n    parts.push('', \\"STYLE POUR CETTE BOÎTE (administrative) : vouvoiement soigné, phrases complètes et courtoises, \\\\\\"Merci d'avance pour votre retour.\\\\\\" avant la formule de fin (\\\\\\"Cordialement,\\\\\\"), aucune familiarité. Écris au nom de l'entreprise (« nous »), pas à la première personne du singulier.\\");\\n  }\\n}\\nif (s && s.draft && s.draft.body) {\\n  const d = s.draft;\\n  parts.push('', 'BROUILLON EN COURS :', `À : ${d.to_name || ''} <${d.to_address || 'adresse inconnue'}>`, `Objet : ${d.subject || ''}`, 'Corps :', d.body);\\n}\\nif (s && s.candidates && s.candidates.length) {\\n  parts.push('', 'ADRESSES PROPOSÉES POUR LE DESTINATAIRE (il peut répondre par un numéro) :');\\n  s.candidates.forEach((c, i) => parts.push(`${i + 1}) ${c.name ? c.name + ' ' : ''}<${c.address}>`));\\n}\\nreturn [{ json: { ...j, prompt: parts.join('\\\\n') } }];\\n","notice":""},"type":"n8n-nodes-base.code","typeVersion":2,"position":[2750,900],"id":"3e7a8d26-7eeb-45f0-b8a1-41342ab747e4","name":"Préparer l'appel Claude (réponse)"},{"parameters":{"notice":"","promptType":"define","text":"={{ $json.prompt }}","hasOutputParser":false,"needsFallback":false,"messages":{"messageValues":[{"type":"SystemMessagePromptTemplate","message":"Tu es l'assistant de rédaction d'e-mails de Valentin Caufriez, gérant d'EBANISTA (menuiserie / ébénisterie sur mesure). Valentin te dicte par Telegram, en langage courant, un e-mail à envoyer (destinataire, sujet, contenu). Tu rédiges l'e-mail à sa place, dans son style ; ensuite il choisit la boîte d'envoi et valide.\\n\\nTu reçois son message, et éventuellement le brouillon en cours (à réviser) et une liste numérotée d'adresses proposées.\\n\\nRéponds UNIQUEMENT par un objet JSON, sans texte autour :\\n{\\n  \\"intent\\": \\"draft\\" | \\"revise\\" | \\"reply\\" | \\"cancel\\" | \\"other\\",\\n  \\"to_name\\": \\"nom du destinataire\\" ou null,\\n  \\"to_address\\": \\"adresse e-mail\\" ou null,\\n  \\"subject\\": \\"objet\\" ou null,\\n  \\"body\\": \\"corps complet du mail, formule de politesse comprise, SANS signature\\" ou null,\\n  \\"reply\\": \\"message court à afficher à Valentin\\" ou null,\\n  \\"find\\": {\\"sender\\": \\"expéditeur, société ou personne cité(e)\\" ou null, \\"subject\\": \\"mots du sujet cités\\" ou null, \\"box\\": \\"v.caufriez\\" | \\"contact\\" | null} ou null,\\n  \\"instructions\\": \\"ce que Valentin veut dire dans la réponse\\" ou null\\n}\\n\\nINTENTIONS :\\n- \\"draft\\" : nouvelle demande d'e-mail.\\n- \\"revise\\" : il modifie le brouillon en cours (ajoute, retire, raccourcit, change le ton, corrige un détail). Change uniquement ce qui est demandé, garde le reste, et renvoie le mail complet à jour.\\n- \\"reply\\" : il demande de RÉPONDRE à un mail déjà reçu (« réponds au mail de Dispano sur le devis », « réponds à Mme Martin », « réponds au dernier mail de contact »). Renseigne \\"find\\" (qui a écrit, mots du sujet, boîte si précisée) et \\"instructions\\" (ce qu'il veut dire dans la réponse, ou null s'il ne dit rien). Ne rédige PAS la réponse à ce stade : \\"body\\" reste null. Aucune adresse n'est nécessaire.\\n- \\"cancel\\" : il abandonne ce brouillon.\\n- Dans le champ \\"reply\\", vouvoie toujours Valentin.\\n- \\"other\\" : ce n'est pas une demande de mail (question, remerciement, message flou). Réponds brièvement dans \\"reply\\" et explique au besoin comment demander un mail : à qui, quel sujet, ce qu'il faut dire.\\n\\nDESTINATAIRE :\\n- to_address : seulement si une adresse figure dans son message ou dans le brouillon en cours, ou s'il choisit un numéro dans la liste d'adresses proposées. N'invente JAMAIS une adresse e-mail. Sinon null (avec to_name si tu as un nom).\\n- Si l'objet n'est pas dicté, propose un objet court et pertinent.\\n\\nRÉPONSE À UN MAIL REÇU :\\n- Si le message contient un bloc \\"MAIL REÇU AUQUEL TU RÉPONDS\\", rédige la réponse à ce mail : intent \\"draft\\" (ou \\"revise\\" si un brouillon existe déjà), et renvoie seulement le corps de la réponse dans \\"body\\". to_address, to_name et subject seront remplis automatiquement : mets-les à null.\\n- Réponds précisément à ce que dit le mail reçu, en suivant les instructions de Valentin. Ne cite pas le mail reçu (il sera cité automatiquement). Applique les mêmes règles d'invention et de style.\\n\\nSTYLE DU CORPS (celui de Valentin) :\\n- Court et direct, 3 à 8 lignes en général, paragraphes très courts, aucune formule ampoulée.\\n- Vouvoiement par défaut ; tutoiement (\\"Salut Prénom,\\") seulement s'il le demande ou indique que le destinataire est un proche ou un fournisseur habituel.\\n- COHÉRENCE : choisis une seule forme (vouvoiement OU tutoiement) et garde-la dans tout le mail, salutation et formule de politesse comprises. Ne mélange jamais \\"vous\\" et \\"tu\\", ni \\"Bonjour,\\" avec du tutoiement.\\n- Salutation : \\"Bonjour,\\" ou \\"Bonjour Prénom,\\" ; \\"Salut Prénom,\\" en tutoiement.\\n- Commandes et demandes de prix : liste à tirets, une quantité ou une référence par ligne.\\n- Termine par une formule de politesse seule : \\"Cordialement,\\" (ou \\"À bientôt,\\" / \\"Bien à toi,\\" en tutoiement). Ne mets AUCUN nom ni signature après : la signature est ajoutée automatiquement.\\n\\nRÈGLES STRICTES :\\n- N'invente JAMAIS un prix, un délai, une date, une quantité, une référence, une dimension ni un engagement qu'il n'a pas dicté. S'il manque une information indispensable, écris [À COMPLÉTER : ce qu'il faut préciser] à l'endroit voulu.\\n- Ne mets pas l'objet dans le corps. N'ajoute ni commentaire, ni \\"Voici le mail\\".\\n- Écris en français, sauf si Valentin demande une autre langue."}]},"batching":{}},"type":"@n8n/n8n-nodes-langchain.chainLlm","typeVersion":1.9,"position":[3000,900],"id":"b81bc1d8-d7a1-4772-ba09-231f8794966a","name":"Rédiger la réponse avec Claude"},{"parameters":{"notice":"","model":{"__rl":true,"mode":"list","value":"claude-sonnet-4-6","cachedResultName":"Claude Sonnet 4.6"},"options":{"temperature":0.3}},"type":"@n8n/n8n-nodes-langchain.lmChatAnthropic","typeVersion":1.5,"position":[3040,1100],"id":"8551e8d8-4628-4330-b957-fe28df9399e0","name":"Modèle Claude (réponse)","credentials":{"anthropicApi":{"id":"FRxZizEr7zCaHHZp","name":"Claude API"}}},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"// Applique la réponse de Claude à la conversation (brouillon, réponse à un mail, annulation, question) et décide de la suite\\nconst j = $('Normaliser la mise à jour').first().json;\\nconst raw = String($input.first().json.text || '');\\nlet out = null;\\ntry { out = JSON.parse(raw.match(/\\\\{[\\\\s\\\\S]*\\\\}/)[0]); } catch (e) { out = null; }\\n\\nconst sd = $getWorkflowStaticData('global');\\nsd.sessions = sd.sessions || {};\\nconst key = String(j.chat_id);\\nconst prev = sd.sessions[key];\\nconst say = (text) => [{ json: { chat_id: j.chat_id, text, next: 'message' } }];\\nconst reSubject = (s) => 'Re: ' + String(s || '').replace(/^\\\\s*((re|ré)\\\\s*:\\\\s*)+/i, '').trim();\\n\\nif (!out) return say(\\"Je n'ai pas bien compris. Pouvez-vous reformuler votre demande ?\\");\\nif (out.intent === 'cancel') { delete sd.sessions[key]; return say('Brouillon annulé.'); }\\nif (out.intent === 'other') return say(out.reply || \\"Dites-moi à qui écrire, le sujet et ce qu'il faut dire (ou « réponds au mail de … »), et je prépare le mail.\\");\\n\\n// demande de réponse à un mail déjà reçu : on retrouve d'abord le mail dans le registre\\nif (out.intent === 'reply') {\\n  sd.sessions[key] = { state: 'reply_search', find: out.find || {}, instructions: out.instructions || '', updated: Date.now() };\\n  return [{ json: { chat_id: j.chat_id, next: 'find' } }];\\n}\\n\\nconst okMail = (a) => (typeof a === 'string' && /^[^\\\\s@<>]+@[^\\\\s@<>]+\\\\.[^\\\\s@<>]+$/.test(a.trim())) ? a.trim() : null;\\nconst d = (prev && prev.draft) || {};\\n\\n// réponse à un mail reçu (première rédaction, ou révision d'un brouillon de réponse)\\nconst replyTo = prev && prev.reply_to;\\nif (replyTo && (prev.reply_pending || (out.intent === 'revise' && prev.draft))) {\\n  const body = out.body || d.body || null;\\n  const nd = { to_name: replyTo.from_name || null, to_address: replyTo.from_address, subject: reSubject(replyTo.subject), body };\\n  sd.sessions[key] = { state: 'draft', draft: nd, reply_to: replyTo, candidates: null, updated: Date.now() };\\n  if (!body) return say(out.reply || 'Que voulez-vous répondre ?');\\n  return [{ json: { chat_id: j.chat_id, next: 'decide', lookup_name: '' } }];\\n}\\n\\nlet nd;\\nif (out.intent === 'revise' && prev && prev.draft) {\\n  nd = {\\n    to_name: out.to_name || d.to_name || null,\\n    to_address: okMail(out.to_address) || d.to_address || null,\\n    subject: out.subject || d.subject || null,\\n    body: out.body || d.body || null,\\n  };\\n} else {\\n  nd = { to_name: out.to_name || null, to_address: okMail(out.to_address), subject: out.subject || null, body: out.body || null };\\n}\\nsd.sessions[key] = { state: 'draft', draft: nd, candidates: null, updated: Date.now() };\\n\\nif (!nd.body) return say(out.reply || 'Que voulez-vous dire dans ce mail ?');\\nconst needLookup = !nd.to_address && !!nd.to_name;\\nreturn [{ json: { chat_id: j.chat_id, next: needLookup ? 'lookup' : 'decide', lookup_name: nd.to_name || '' } }];\\n","notice":""},"type":"n8n-nodes-base.code","typeVersion":2,"position":[3250,900],"id":"595d25eb-611e-4c95-ba4c-5b5e33108363","name":"Appliquer la réponse (réponse)"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"dcdebf43-b6eb-4a97-b4a3-8f25a7a19244","leftValue":"={{ $json.next }}","rightValue":"decide","operator":{"type":"string","operation":"equals"}}],"combinator":"and"},"looseTypeValidation":false,"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[3500,900],"id":"57f86157-4420-425b-bb76-5e709f3be781","name":"Réponse prête ?"},{"parameters":{"resource":"message","operation":"sendMessage","chatId":"={{ $json.chat_id }}","text":"={{ $json.text }}","replyMarkup":"inlineKeyboard","inlineKeyboard":{"rows":[{"row":{"buttons":[{"text":"={{ $json.label_v }}","additionalFields":{"callback_data":"send:v"}}]}},{"row":{"buttons":[{"text":"={{ $json.label_c }}","additionalFields":{"callback_data":"send:c"}}]}},{"row":{"buttons":[{"text":"❌ Annuler","additionalFields":{"callback_data":"cancel"}}]}}]},"additionalFields":{"appendAttribution":false}},"type":"n8n-nodes-base.telegram","typeVersion":1.2,"position":[3300,450],"id":"e4b0fd20-bdeb-4b6d-8e87-b5aeecb656f5","name":"Aperçu avec boutons","credentials":{"telegramApi":{"id":"duvmoy6UkxnbnBdr","name":"Ebanista Mails"}},"webhookId":"70ac125f-f4cf-4e75-97c9-50dcc1f4bd86"}],"connections":{"Webhook Telegram":{"main":[[{"node":"Normaliser la mise à jour","type":"main","index":0}]]},"Normaliser la mise à jour":{"main":[[{"node":"Bouton ?","type":"main","index":0}]]},"Bouton ?":{"main":[[{"node":"Accuser réception du bouton","type":"main","index":0}],[{"node":"Demande à Claude ?","type":"main","index":0}]]},"Demande à Claude ?":{"main":[[{"node":"Préparer l'appel Claude","typ