358	{"id":"wNqeTKj68eF0lqFJ","name":"Assistant e-mails Telegram","nodes":[{"parameters":{"multipleMethods":false,"httpMethod":"POST","path":"assistant-mails-0e623b6c920aa52f22bb7772","authentication":"headerAuth","responseMode":"lastNode","responseData":"firstEntryJson","options":{}},"type":"n8n-nodes-base.webhook","typeVersion":2,"position":[0,0],"id":"da1a8ff1-7b1d-4916-ae96-054a451d0d96","name":"Webhook Telegram","credentials":{"httpHeaderAuth":{"id":"86dpp3Vg9wZOdnpT","name":"Pont Telegram (secret)"}},"webhookId":"17a4c956-8f6a-4b73-89a3-d2c3c624a13a"},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"// Réception d'une mise à jour Telegram : filtre l'expéditeur, évite les doublons, retrouve la conversation en cours\\nconst ALLOWED = 8848139246;\\nconst upd = $input.first().json.body || {};\\nconst sd = $getWorkflowStaticData('global');\\nsd.seen = sd.seen || [];\\nsd.sessions = sd.sessions || {};\\n\\nconst msg = upd.message, cb = upd.callback_query;\\nconst from = (msg && msg.from) || (cb && cb.from) || {};\\nconst chat = (msg && msg.chat) || (cb && cb.message && cb.message.chat) || {};\\n\\n// seul le compte de Valentin est autorisé : tout autre expéditeur est ignoré sans réponse\\nif (Number(from.id) !== ALLOWED || Number(chat.id) !== ALLOWED) return [];\\n\\n// une même mise à jour n'est jamais traitée deux fois\\nif (upd.update_id !== undefined) {\\n  if (sd.seen.includes(upd.update_id)) return [];\\n  sd.seen.push(upd.update_id);\\n  if (sd.seen.length > 100) sd.seen = sd.seen.slice(-100);\\n}\\n\\nconst key = String(chat.id);\\nlet s = sd.sessions[key];\\nif (s && Date.now() - (s.updated || 0) > 45 * 60 * 1000) { delete sd.sessions[key]; s = undefined; } // conversation expirée après 45 min\\n\\nlet route = 'message', text = '';\\nif (cb) route = 'callback';\\nelse if (msg && msg.text) route = 'claude';\\nelse text = \\"Je ne sais traiter que du texte pour l'instant. Écrivez-moi (ou dictez avec le clavier de votre téléphone) à qui écrire, le sujet et ce qu'il faut dire.\\";\\n\\nreturn [{ json: {\\n  route, text, chat_id: chat.id, update_id: upd.update_id,\\n  user_text: msg ? (msg.text || '') : '',\\n  cb_data: cb ? (cb.data || '') : '', cb_id: cb ? cb.id : '',\\n  session: s || null,\\n} }];\\n","notice":""},"type":"n8n-nodes-base.code","typeVersion":2,"position":[250,0],"id":"553fcad7-f3e2-4eb3-a743-4c5557786be6","name":"Normaliser la mise à jour"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"2eb2cd49-dbd0-48b0-b32d-c35ab46f8353","leftValue":"={{ $json.route }}","rightValue":"callback","operator":{"type":"string","operation":"equals"}}],"combinator":"and"},"looseTypeValidation":false,"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[500,0],"id":"2265e5f5-cc68-4f9c-83e2-32b62bb81457","name":"Bouton ?"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"756deb36-156c-44f2-8d26-fdb8ad9ee285","leftValue":"={{ $json.route }}","rightValue":"claude","operator":{"type":"string","operation":"equals"}}],"combinator":"and"},"looseTypeValidation":false,"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[500,400],"id":"cc121581-ebad-4fdf-812c-1ad69244c3d2","name":"Demande à Claude ?"},{"parameters":{"resource":"message","operation":"sendMessage","chatId":"={{ $json.chat_id }}","text":"={{ $json.text }}","replyMarkup":"none","additionalFields":{"appendAttribution":false}},"type":"n8n-nodes-base.telegram","typeVersion":1.2,"position":[2400,400],"id":"d9990c52-938b-489a-8039-5fc0de70214f","name":"Message texte","credentials":{"telegramApi":{"id":"duvmoy6UkxnbnBdr","name":"Ebanista Mails"}},"webhookId":"e6a6c79c-ef69-4a50-b40a-fbf2ab831b1c"},{"parameters":{"resource":"callback","operation":"answerQuery","queryId":"={{ $json.cb_id }}","additionalFields":{}},"type":"n8n-nodes-base.telegram","typeVersion":1.2,"position":[750,-200],"id":"d8165235-9579-49dc-bd1a-4dfaa0e177ed","name":"Accuser réception du bouton","credentials":{"telegramApi":{"id":"duvmoy6UkxnbnBdr","name":"Ebanista Mails"}},"onError":"continueRegularOutput","webhookId":"3f9a67c7-eb0c-4caf-814d-6b142d1e8250"},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"// Traite un clic sur un bouton : annulation ou envoi (préparation du message à expédier)\\nconst j = $('Normaliser la mise à jour').first().json;\\nconst sd = $getWorkflowStaticData('global');\\nsd.sessions = sd.sessions || {};\\nconst key = String(j.chat_id);\\nconst s = sd.sessions[key];\\nconst say = (text) => [{ json: { chat_id: j.chat_id, text, next: 'message' } }];\\n\\nif (j.cb_data === 'cancel') { delete sd.sessions[key]; return say('Brouillon annulé.'); }\\nconst m = /^send:(v|c)$/.exec(j.cb_data || '');\\nif (!m) return say('Action inconnue.');\\nif (!s || s.state !== 'ready' || !s.draft || !s.draft.to_address || !s.draft.body) {\\n  return say(\\"Ce brouillon n'est plus en attente (déjà envoyé, annulé ou expiré). Redites-moi ce que vous voulez envoyer.\\");\\n}\\nconst BOX = {\\n  v: { from: 'v.caufriez@ebanista.fr', fromName: 'Valentin Caufriez', signature: 'Valentin Caufriez', label: 'v.caufriez@ebanista.fr' },\\n  c: { from: 'contact@ebanista.fr', fromName: 'Ebanista', signature: \\"L'équipe Ebanista\\", label: 'contact@ebanista.fr' },\\n}[m[1]];\\ns.state = 'sending'; s.updated = Date.now();\\nconst d = s.draft;\\nreturn [{ json: {\\n  chat_id: j.chat_id, next: 'send', box: m[1], label: BOX.label,\\n  from: BOX.from, fromName: BOX.fromName,\\n  from_header: `${BOX.fromName} <${BOX.from}>`,\\n  to: d.to_address, to_name: d.to_name || '', subject: d.subject || '(sans objet)',\\n  text: `${d.body.replace(/\\\\s+$/, '')}\\\\n\\\\n${BOX.signature}`,\\n} }];\\n","notice":""},"type":"n8n-nodes-base.code","typeVersion":2,"position":[1000,-200],"id":"2508fe67-1f92-443c-ae2f-5ba3d4aff3a6","name":"Traiter le bouton"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"6d87b283-2b18-4ce9-9b50-9c871d4ad98f","leftValue":"={{ $json.next }}","rightValue":"send","operator":{"type":"string","operation":"equals"}}],"combinator":"and"},"looseTypeValidation":false,"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[1250,-200],"id":"be3bc941-9a2a-497f-9755-d17394354426","name":"Envoi demandé ?"},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"// Confirme l'envoi à Valentin et clôt la conversation\\nconst t = $('Traiter le bouton').first().json;\\nconst sd = $getWorkflowStaticData('global');\\nsd.sessions = sd.sessions || {};\\ndelete sd.sessions[String(t.chat_id)];\\nlet copyOk = true;\\ntry {\\n  const r = $input.first().json;\\n  if (!r || r.error || r.deleted === false) copyOk = false;\\n} catch (e) { copyOk = false; }\\nreturn [{ json: { chat_id: t.chat_id, text: `✅ Mail envoyé depuis ${t.label}\\\\nÀ : ${t.to}\\\\nObjet : ${t.subject}` + (copyOk ? '\\\\nUne copie est enregistrée dans Envoyés.' : \\"\\\\n⚠️ La copie dans Envoyés n'a pas pu être enregistrée.\\") } }];\\n","notice":""},"type":"n8n-nodes-base.code","typeVersion":2,"position":[2150,-200],"id":"9b3e560e-87a7-4f71-9992-c3fb0cfffced","name":"Confirmer l'envoi"},{"parameters":{"resource":"message","operation":"sendMessage","chatId":"={{ $json.chat_id }}","text":"={{ $json.text }}","replyMarkup":"none","additionalFields":{"appendAttribution":false}},"type":"n8n-nodes-base.telegram","typeVersion":1.2,"position":[2400,-200],"id":"eec69fa0-eb48-41bc-ad4e-69880134e1ab","name":"Confirmation Telegram","credentials":{"telegramApi":{"id":"duvmoy6UkxnbnBdr","name":"Ebanista Mails"}},"webhookId":"692af0f2-9cc1-48f6-b19b-539a8e0c72f7"},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"// L'envoi a échoué : on remet le brouillon en attente pour pouvoir réessayer\\nconst t = $('Traiter le bouton').first().json;\\nconst sd = $getWorkflowStaticData('global');\\nconst s = (sd.sessions || {})[String(t.chat_id)];\\nif (s) { s.state = 'ready'; s.updated = Date.now(); }\\nlet why = '';\\ntry { why = String($input.first().json.error && ($input.first().json.error.message || $input.first().json.error) || '').slice(0, 200); } catch (e) {}\\nreturn [{ json: { chat_id: t.chat_id, text: `❌ L'envoi depuis ${t.label} a échoué${why ? ' : ' + why : ''}.\\\\nLe brouillon est conservé : vous pouvez réessayer avec le même bouton ou choisir l'autre boîte.` } }];\\n","notice":""},"type":"n8n-nodes-base.code","typeVersion":2,"position":[1900,-500],"id":"e54ceddd-dcc3-4a70-b28d-be7ea8474097","name":"Échec de l'envoi"},{"parameters":{"resource":"email","operation":"send","fromEmail":"={{ $json.from_header }}","toEmail":"={{ $json.to }}","subject":"={{ $json.subject }}","emailFormat":"text","text":"={{ $json.text }}","options":{"appendAttribution":false}},"type":"n8n-nodes-base.emailSend","typeVersion":2.1,"position":[1700,-200],"id":"74903f0e-db1c-4568-9ddc-2a6f20b6d160","name":"Envoi depuis v.caufriez@ebanista.fr","credentials":{"smtp":{"id":"HpY9yQWKI4eEr1b8","name":"SMTP - v.caufriez@ebanista.fr"}},"onError":"continueErrorOutput","webhookId":"e58bc334-f4f3-4474-9321-90982e56b399"},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"// Compose la copie du mail envoyé (RFC822) pour le dossier Envoyés de la boîte\\nconst t = $('Traiter le bouton').first().json;\\nconst info = $input.first().json;\\nconst CRLF = '\\\\r\\\\n';\\nconst b64 = (s) => Buffer.from(s, 'utf8').toString('base64');\\nconst isAscii = (s) => /^[\\\\x20-\\\\x7e]*$/.test(s);\\nconst encodeHeader = (s) => {\\n  if (isAscii(s)) return s;\\n  const chars = Array.from(s), parts = [];\\n  for (let i = 0; i < chars.length; i += 10) parts.push(`=?UTF-8?B?${b64(chars.slice(i, i + 10).join(''))}?=`);\\n  return parts.join(CRLF + ' ');\\n};\\nconst name = (n) => !n ? '' : (!isAscii(n) ? `=?UTF-8?B?${b64(n)}?=` : (/[^\\\\w .'-]/.test(n) ? `\\"${n.replace(/([\\"\\\\\\\\])/g, '\\\\\\\\$1')}\\"` : n));\\nconst msgId = info.messageId || `<copie-${Date.now()}@ebanista.fr>`;\\nconst headers = [\\n  `From: ${name(t.fromName)} <${t.from}>`,\\n  `To: ${t.to_name ? name(t.to_name) + ' ' : ''}<${t.to}>`,\\n  `Subject: ${encodeHeader(t.subject)}`,\\n  `Date: ${new Date().toUTCString().replace('GMT', '+0000')}`,\\n  `Message-ID: ${msgId}`,\\n  'MIME-Version: 1.0',\\n  'Content-Type: text/plain; charset=UTF-8',\\n  'Content-Transfer-Encoding: base64',\\n];\\nconst body = b64(t.text.replace(/\\\\r?\\\\n/g, CRLF)).replace(/(.{76})/g, '$1' + CRLF);\\nreturn [{ json: { rfc822: headers.join(CRLF) + CRLF + CRLF + body + CRLF } }];\\n","notice":""},"type":"n8n-nodes-base.code","typeVersion":2,"position":[1900,-200],"id":"04779f42-df5c-4356-adf8-9dc1435c6775","name":"Composer la copie v"},{"parameters":{"authentication":"coreImapAccount","resource":"email","operation":"createDraft","destinationMailbox":{"__rl":true,"mode":"path","value":"Sent"},"inputFormat":"rfc822","rfc822":"={{ $json.rfc822 }}"},"type":"n8n-nodes-imap.imap","typeVersion":1,"position":[2000,-200],"id":"18c4665a-3b3d-4204-a5f1-cb444fdaa4e7","name":"Enregistrer la copie v","credentials":{"imap":{"id":"wVKdbE1JQnIB1kzf","name":"IMAP - v.caufriez@ebanista.fr"}},"onError":"continueRegularOutput"},{"parameters":{"authentication":"coreImapAccount","resource":"email","operation":"setEmailFlags","mailboxPath":{"__rl":true,"mode":"path","value":"Sent"},"emailUid":"={{ $json.uid }}","flags":{"\\\\Draft":false,"\\\\Seen":true}},"type":"n8n-nodes-imap.imap","typeVersion":1,"position":[2100,-200],"id":"2e30f26b-b45e-4ccb-b5ab-e25e225d06db","name":"Marquer la copie lue v","credentials":{"imap":{"id":"wVKdbE1JQnIB1kzf","name":"IMAP - v.caufriez@ebanista.fr"}},"onError":"continueRegularOutput"},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"// Construit le message envoyé à Claude : demande de Valentin + brouillon en cours + adresses proposées\\nconst j = $input.first().json;\\nconst s = j.session;\\nconst parts = ['MESSAGE DE VALENTIN :', j.user_text];\\nif (s && s.draft && s.draft.body) {\\n  const d = s.draft;\\n  parts.push('', 'BROUILLON EN COURS :', `À : ${d.to_name || ''} <${d.to_address || 'adresse inconnue'}>`, `Objet : ${d.subject || ''}`, 'Corps :', d.body);\\n}\\nif (s && s.candidates && s.candidates.length) {\\n  parts.push('', 'ADRESSES PROPOSÉES POUR LE DESTINATAIRE (il peut répondre par un numéro) :');\\n  s.candidates.forEach((c, i) => parts.push(`${i + 1}) ${c.name ? c.name + ' ' : ''}<${c.address}>`));\\n}\\nreturn [{ json: { ...j, prompt: parts.join('\\\\n') } }];\\n","notice":""},"type":"n8n-nodes-base.code","typeVersion":2,"position":[750,400],"id":"f6c74975-d67b-4357-a0f8-c93b38b79bff","name":"Préparer l'appel Claude"},{"parameters":{"notice":"","promptType":"define","text":"={{ $json.prompt }}","hasOutputParser":false,"needsFallback":false,"messages":{"messageValues":[{"type":"SystemMessagePromptTemplate","message":"Tu es l'assistant de rédaction d'e-mails de Valentin Caufriez, gérant d'EBANISTA (menuiserie / ébénisterie sur mesure). Valentin te dicte par Telegram, en langage courant, un e-mail à envoyer (destinataire, sujet, contenu). Tu rédiges l'e-mail à sa place, dans son style ; ensuite il choisit la boîte d'envoi et valide.\\n\\nTu reçois son message, et éventuellement le brouillon en cours (à réviser) et une liste numérotée d'adresses proposées.\\n\\nRéponds UNIQUEMENT par un objet JSON, sans texte autour :\\n{\\n  \\"intent\\": \\"draft\\" | \\"revise\\" | \\"cancel\\" | \\"other\\",\\n  \\"to_name\\": \\"nom du destinataire\\" ou null,\\n  \\"to_address\\": \\"adresse e-mail\\" ou null,\\n  \\"subject\\": \\"objet\\" ou null,\\n  \\"body\\": \\"corps complet du mail, formule de politesse comprise, SANS signature\\" ou null,\\n  \\"reply\\": \\"message court à afficher à Valentin\\" ou null\\n}\\n\\nINTENTIONS :\\n- \\"draft\\" : nouvelle demande d'e-mail.\\n- \\"revise\\" : il modifie le brouillon en cours (ajoute, retire, raccourcit, change le ton, corrige un détail). Change uniquement ce qui est demandé, garde le reste, et renvoie le mail complet à jour.\\n- \\"cancel\\" : il abandonne ce brouillon.\\n- \\"other\\" : ce n'est pas une demande de mail (question, remerciement, message flou). Réponds brièvement dans \\"reply\\" et explique au besoin comment demander un mail : à qui, quel sujet, ce qu'il faut dire.\\n\\nDESTINATAIRE :\\n- to_address : seulement si une adresse figure dans son message ou dans le brouillon en cours, ou s'il choisit un numéro dans la liste d'adresses proposées. N'invente JAMAIS une adresse e-mail. Sinon null (avec to_name si tu as un nom).\\n- Si l'objet n'est pas dicté, propose un objet court et pertinent.\\n\\nSTYLE DU CORPS (celui de Valentin) :\\n- Court et direct, 3 à 8 lignes en général, paragraphes très courts, aucune formule ampoulée.\\n- Vouvoiement par défaut ; tutoiement (\\"Salut Prénom,\\") seulement s'il le demande ou indique que le destinataire est un proche ou un fournisseur habituel.\\n- Salutation : \\"Bonjour,\\" ou \\"Bonjour Prénom,\\" ; \\"Salut Prénom,\\" en tutoiement.\\n- Commandes et demandes de prix : liste à tirets, une quantité ou une référence par ligne.\\n- Termine par une formule de politesse seule : \\"Cordialement,\\" (ou \\"À bientôt,\\" / \\"Bien à toi,\\" en tutoiement). Ne mets AUCUN nom ni signature après : la signature est ajoutée automatiquement.\\n\\nRÈGLES STRICTES :\\n- N'invente JAMAIS un prix, un délai, une date, une quantité, une référence, une dimension ni un engagement qu'il n'a pas dicté. S'il manque une information indispensable, écris [À COMPLÉTER : ce qu'il faut préciser] à l'endroit voulu.\\n- Ne mets pas l'objet dans le corps. N'ajoute ni commentaire, ni \\"Voici le mail\\".\\n- Écris en français, sauf si Valentin demande une autre langue."}]},"batching":{}},"type":"@n8n/n8n-nodes-langchain.chainLlm","typeVersion":1.9,"position":[1000,400],"id":"f1306921-6488-4b18-b0b7-0e6d36283c76","name":"Rédiger avec Claude"},{"parameters":{"notice":"","model":{"__rl":true,"mode":"list","value":"claude-sonnet-4-6","cachedResultName":"Claude Sonnet 4.6"},"options":{"temperature":0.3}},"type":"@n8n/n8n-nodes-langchain.lmChatAnthropic","typeVersion":1.5,"position":[1040,620],"id":"540e350d-666c-4c5e-93e1-eb956f8c8157","name":"Modèle Claude (assistant)","credentials":{"anthropicApi":{"id":"FRxZizEr7zCaHHZp","name":"Claude API"}}},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"// Applique la réponse de Claude à la conversation (brouillon, annulation, question) et décide de la suite\\nconst j = $('Normaliser la mise à jour').first().json;\\nconst raw = String($input.first().json.text || '');\\nlet out = null;\\ntry { out = JSON.parse(raw.match(/\\\\{[\\\\s\\\\S]*\\\\}/)[0]); } catch (e) { out = null; }\\n\\nconst sd = $getWorkflowStaticData('global');\\nsd.sessions = sd.sessions || {};\\nconst key = String(j.chat_id);\\nconst prev = sd.sessions[key];\\nconst say = (text) => [{ json: { chat_id: j.chat_id, text, next: 'message' } }];\\n\\nif (!out) return say(\\"Je n'ai pas bien compris. Pouvez-vous reformuler votre demande d'e-mail ?\\");\\nif (out.intent === 'cancel') { delete sd.sessions[key]; return say('Brouillon annulé.'); }\\nif (out.intent === 'other') return say(out.reply || \\"Dites-moi à qui écrire, le sujet et ce qu'il faut dire, et je prépare le mail.\\");\\n\\nconst okMail = (a) => (typeof a === 'string' && /^[^\\\\s@<>]+@[^\\\\s@<>]+\\\\.[^\\\\s@<>]+$/.test(a.trim())) ? a.trim() : null;\\nconst d = (prev && prev.draft) || {};\\nlet nd;\\nif (out.intent === 'revise' && prev && prev.draft) {\\n  nd = {\\n    to_name: out.to_name || d.to_name || null,\\n    to_address: okMail(out.to_address) || d.to_address || null,\\n    subject: out.subject || d.subject || null,\\n    body: out.body || d.body || null,\\n  };\\n} else {\\n  nd = { to_name: out.to_name || null, to_address: okMail(out.to_address), subject: out.subject || null, body: out.body || null };\\n}\\nsd.sessions[key] = { state: 'draft', draft: nd, candidates: null, updated: Date.now() };\\n\\nif (!nd.body) return say(out.reply || 'Que voulez-vous dire dans ce mail ?');\\nconst needLookup = !nd.to_address && !!nd.to_name;\\nreturn [{ json: { chat_id: j.chat_id, next: needLookup ? 'lookup' : 'decide', lookup_name: nd.to_name || '' } }];\\n","notice":""},"type":"n8n-nodes-base.code","typeVersion":2,"position":[1250,400],"id":"4eabee89-1f60-458b-b68d-b35f19334684","name":"Appliquer la réponse de Claude"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"f7acb517-88e5-48b9-87eb-5611c46f276b","leftValue":"={{ $json.next }}","rightValue":"message","operator":{"type":"string","operation":"equals"}}],"combinator":"and"},"looseTypeValidation":false,"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[1500,400],"id":"1345c891-ef25-409f-be27-0d7f21ccab29","name":"Message direct ?"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"4015994c-2f37-49fa-a2ef-0719ece7a17f","leftValue":"={{ $json.next }}","rightValue":"lookup","operator":{"type":"string","operation":"equals"}}],"combinator":"and"},"looseTypeValidation":false,"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[1750,550],"id":"4a8d3c67-78a9-4ff4-b74e-05fe94b8f06f","name":"Recherche d'adresse ?"},{"parameters":{"authentication":"coreImapAccount","resource":"email","operation":"getEmailsList","mailboxPath":{"__rl":true,"mode":"path","value":"Sent"},"emailDateRange":{"since":"={{ $now.minus({ years: 2 }).toISO() }}"},"emailFlags":{},"emailSearchFilters":{"to":"={{ ($('Appliquer la réponse de Claude').first().json.lookup_name || '').split(/\\\\s+/).filter(Boolean).sort((a, b) => b.length - a.length)[0] || 'introuvable-xyz' }}"},"limit":40,"includeParts":[]},"type":"n8n-nodes-imap.imap","typeVersion":1,"position":[2000,700],"id":"649a0dd6-fcfd-40c6-bf40-fc6112e5ba9a","name":"Recherche Envoyés v.caufriez","credentials":{"imap":{"id":"wVKdbE1JQnIB1kzf","name":"IMAP - v.caufriez@ebanista.fr"}},"alwaysOutputData":true,"onError":"continueRegularOutput"},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"// Regroupe en un seul élément les résultats de la recherche dans les Envoyés de v.caufriez@\\nconst found = $input.all().map(i => i.json).filter(j => j && j.envelope && !j.error);\\nreturn [{ json: { found } }];\\n","notice":""},"type":"n8n-nodes-base.code","typeVersion":2,"position":[2200,700],"id":"3ed63703-359b-4fb8-8dda-bd69388bb701","name":"Regrouper les résultats v.caufriez"},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"// Retrouve l'adresse du destinataire à partir de son nom, dans les dossiers Envoyés des deux boîtes\\nconst ctx = $('Appliquer la réponse de Claude').first().json;\\nconst j = $('Normaliser la mise à jour').first().json;\\nconst sd = $getWorkflowStaticData('global');\\nconst key = String(j.chat_id);\\nconst s = sd.sessions[key];\\nconst strip = (t) => String(t || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');\\nconst tokens = strip(ctx.lookup_name).split(/[^a-z0-9]+/).filter(t => t.length >= 2);\\n\\nconst first = ($('Regrouper les résultats v.caufriez').first().json.found) || [];\\nconst second = $input.all().map(i => i.json).filter(x => x && x.envelope && !x.error);\\nconst MINE = ['v.caufriez@ebanista.fr', 'contact@ebanista.fr', 'comptabilite@ebanista.fr'];\\nconst tally = {};\\nfor (const m of [...first, ...second]) {\\n  for (const t of ((m.envelope && m.envelope.to) || [])) {\\n    const addr = String(t.address || '').toLowerCase();\\n    if (!addr || MINE.includes(addr)) continue;\\n    const hay = strip((t.name || '') + ' ' + addr);\\n    if (tokens.length && !tokens.every(tok => hay.includes(tok))) continue;\\n    const e = tally[addr] || (tally[addr] = { address: addr, name: t.name || '', count: 0 });\\n    e.count++;\\n    if (!e.name && t.name) e.name = t.name;\\n  }\\n}\\nconst list = Object.values(tally).sort((a, b) => b.count - a.count);\\nif (s) {\\n  if (list.length === 1 || (list.length > 1 && list[0].count >= 2 * list[1].count && list[0].count >= 2)) {\\n    s.draft.to_address = list[0].address;\\n    if (!s.draft.to_name && list[0].name) s.draft.to_name = list[0].name;\\n  } else if (list.length > 1) {\\n    s.candidates = list.slice(0, 5).map(c => ({ name: c.name, address: c.address }));\\n  }\\n  s.updated = Date.now();\\n}\\nreturn [{ json: { chat_id: j.chat_id } }];\\n","notice":""},"type":"n8n-nodes-base.code","typeVersion":2,"position":[2600,700],"id":"babca67f-c0b1-4319-99c6-01719bdf7859","name":"Retrouver l'adresse"},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"// Décide ce qu'il faut répondre à Valentin : question sur l'adresse, informations manquantes, ou aperçu avec boutons\\nconst j = $('Normaliser la mise à jour').first().json;\\nconst sd = $getWorkflowStaticData('global');\\nconst key = String(j.chat_id);\\nconst s = sd.sessions[key];\\nconst out = (text, preview = false) => [{ json: { chat_id: j.chat_id, text, preview } }];\\nif (!s || !s.draft) return out(\\"Je n'ai plus de brouillon en cours. Redites-moi à qui écrire et ce qu'il faut dire.\\");\\nconst d = s.draft;\\n\\nif (s.candidates && s.candidates.length) {\\n  s.state = 'awaiting_address'; s.updated = Date.now();\\n  const lines = s.candidates.map((c, i) => `${i + 1}) ${c.name ? c.name + ' ' : ''}<${c.address}>`).join('\\\\n');\\n  return out(`Plusieurs adresses possibles pour « ${d.to_name || 'ce destinataire'} » :\\\\n${lines}\\\\n\\\\nRépondez par le numéro, ou donnez-moi directement l'adresse.`);\\n}\\nif (!d.to_address) {\\n  s.state = 'awaiting_address'; s.updated = Date.now();\\n  return out(`Je n'ai pas trouvé l'adresse e-mail de ${d.to_name || 'ce destinataire'}. Pouvez-vous me la donner ?`);\\n}\\nconst missing = (d.body.match(/\\\\[À COMPLÉTER[^\\\\]]*\\\\]/g) || []);\\nconst draftText = `À : ${d.to_name ? d.to_name + ' ' : ''}<${d.to_address}>\\\\nObjet : ${d.subject || '(sans objet)'}\\\\n\\\\n${d.body}`;\\nif (missing.length) {\\n  s.state = 'awaiting_info'; s.updated = Date.now();\\n  return out(`Il manque des informations avant de pouvoir envoyer :\\\\n${missing.map(m => '• ' + m).join('\\\\n')}\\\\n\\\\nPrécisez-les-moi et je mets le brouillon à jour.\\\\n\\\\n— Brouillon actuel —\\\\n${draftText}`);\\n}\\ns.state = 'ready'; s.updated = Date.now();\\nreturn out(`✉️ Brouillon prêt\\\\n\\\\n${draftText}\\\\n\\\\n(La signature est ajoutée selon la boîte choisie.)\\\\nChoisissez la boîte d'envoi, ou dites-moi quoi modifier.`, true);\\n","notice":""},"type":"n8n-nodes-base.code","typeVersion":2,"position":[2800,550],"id":"22ec8d18-b879-4978-bce8-eccc201bdbf8","name":"Décider du message"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"50f331c1-eefc-46b3-a713-e32a6d7fd480","leftValue":"={{ String($json.preview) }}","rightValue":"true","operator":{"type":"string","operation":"equals"}}],"combinator":"and"},"looseTypeValidation":false,"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[3050,550],"id":"5b7b31cf-5756-4e4a-b13b-537395285f7a","name":"Aperçu ?"},{"parameters":{"resource":"message","operation":"sendMessage","chatId":"={{ $json.chat_id }}","text":"={{ $json.text }}","replyMarkup":"inlineKeyboard","inlineKeyboard":{"rows":[{"row":{"buttons":[{"text":"✉️ Envoyer depuis v.caufriez@ebanista.fr","additionalFields":{"callback_data":"send:v"}}]}},{"row":{"buttons":[{"text":"❌ Annuler","additionalFields":{"callback_data":"cancel"}}]}}]},"additionalFields":{"appendAttribution":false}},"type":"n8n-nodes-base.telegram","typeVersion":1.2,"positio