/.test(msg.text)) { route = 'reply_choose'; pick = Number(msg.text.trim()); }\\nelse if (msg && msg.text) route = 'claude';\\nelse text = \\"Je ne sais traiter que du texte pour l'instant. Écrivez-moi (ou dictez avec le clavier de votre téléphone) à qui écrire, le sujet et ce qu'il faut dire.\\";\\n\\nreturn [{ json: {\\n  route, text, pick, chat_id: chat.id, update_id: upd.update_id,\\n  user_text: msg ? (msg.text || '') : '',\\n  cb_data: cb ? (cb.data || '') : '', cb_id: cb ? cb.id : '',\\n  session: s || null,\\n} }];\\n","notice":""},"type":"n8n-nodes-base.code","typeVersion":2,"position":[250,0],"id":"5db07f2f-8a68-4e96-b514-7fbbbec3dea4","name":"Normaliser la mise à jour"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"fa83ce52-00f0-44d4-9ed2-1d0584983fb7","leftValue":"={{ $json.route }}","rightValue":"callback","operator":{"type":"string","operation":"equals"}}],"combinator":"and"},"looseTypeValidation":false,"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[500,0],"id":"3f487ace-2648-4eda-a531-20fa17d008ec","name":"Bouton ?"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"736c8e9e-af59-4fc8-aa72-3725697e622f","leftValue":"={{ $json.route }}","rightValue":"claude","operator":{"type":"string","operation":"equals"}}],"combinator":"and"},"looseTypeValidation":false,"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[500,400],"id":"0422969f-19dc-4d83-89d3-4f16bb60d858","name":"Demande à Claude ?"},{"parameters":{"resource":"message","operation":"sendMessage","chatId":"={{ $json.chat_id }}","text":"={{ $json.text }}","replyMarkup":"none","additionalFields":{"appendAttribution":false}},"type":"n8n-nodes-base.telegram","typeVersion":1.2,"position":[2400,400],"id":"2762791a-bbfb-4326-801d-1b850c711d5f","name":"Message texte","credentials":{"telegramApi