389	{"id":"wNqeTKj68eF0lqFJ","name":"Assistant e-mails Telegram","nodes":[{"parameters":{"multipleMethods":false,"httpMethod":"POST","path":"assistant-mails-0e623b6c920aa52f22bb7772","authentication":"headerAuth","responseMode":"lastNode","responseData":"firstEntryJson","options":{}},"type":"n8n-nodes-base.webhook","typeVersion":2,"position":[0,0],"id":"dd64731d-8bbd-4de9-8f21-ffa941af3021","name":"Webhook Telegram","credentials":{"httpHeaderAuth":{"id":"86dpp3Vg9wZOdnpT","name":"Pont Telegram (secret)"}},"webhookId":"dc32adeb-4ced-455b-91da-6dbc2c5a5e60"},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"// Réception d'une mise à jour Telegram : filtre l'expéditeur, évite les doublons, retrouve la conversation en cours\\nconst ALLOWED = 8848139246;\\nconst upd = $input.first().json.body || {};\\nconst sd = $getWorkflowStaticData('global');\\nsd.seen = sd.seen || [];\\nsd.sessions = sd.sessions || {};\\n\\nconst msg = upd.message, cb = upd.callback_query;\\nconst from = (msg && msg.from) || (cb && cb.from) || {};\\nconst chat = (msg && msg.chat) || (cb && cb.message && cb.message.chat) || {};\\n\\n// seul le compte de Valentin est autorisé : tout autre expéditeur est ignoré sans réponse\\nif (Number(from.id) !== ALLOWED || Number(chat.id) !== ALLOWED) return [{ json: { route: 'ignore' } }];\\n\\n// une même mise à jour n'est jamais traitée deux fois\\nif (upd.update_id !== undefined) {\\n  if (sd.seen.includes(upd.update_id)) return [{ json: { route: 'ignore' } }];\\n  sd.seen.push(upd.update_id);\\n  if (sd.seen.length > 100) sd.seen = sd.seen.slice(-100);\\n}\\n\\nconst key = String(chat.id);\\nlet s = sd.sessions[key];\\nif (s && Date.now() - (s.updated || 0) > 45 * 60 * 1000) { delete sd.sessions[key]; s = undefined; } // conversation expirée après 45 min\\n\\nlet route = 'message', text = '', pick = 0;\\nif (cb) route = 'callback';\\nelse if (msg && msg.text && s && s.state === 'reply_pick' && s.mail_candidates && /^\\\\s*[1-9]\\\\s*$/.test(msg.text)) { route = 'reply_choose'; pick = Number(msg.text.trim()); }\\nelse if (msg && msg.text) route = 'claude';\\nelse text = \\"Je ne sais traiter que du texte pour l'instant. Écrivez-moi (ou dictez avec le clavier de votre téléphone) à qui écrire, le sujet et ce qu'il faut dire.\\";\\n\\nreturn [{ json: {\\n  route, text, pick, chat_id: chat.id, update_id: upd.update_id,\\n  user_text: msg ? (msg.text || '') : '',\\n  cb_data: cb ? (cb.data || '') : '', cb_id: cb ? cb.id : '',\\n  session: s || null,\\n} }];\\n","notice":""},"type":"n8n-nodes-base.code","typeVersion":2,"position":[250,0],"id":"bc68baa0-d493-4a9f-adba-68f65b96e229","name":"Normaliser la mise à jour"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"3dc22ba5-01cc-491a-8b89-2e2b12d89185","leftValue":"={{ $json.route }}","rightValue":"callback","operator":{"type":"string","operation":"equals"}}],"combinator":"and"},"looseTypeValidation":false,"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[500,0],"id":"28e8da58-a310-4a7d-a901-3ea58452df03","name":"Bouton ?"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"daa5aa2a-5653-49ef-8fec-529a8e4a67e0","leftValue":"={{ $json.route }}","rightValue":"claude","operator":{"type":"string","operation":"equals"}}],"combinator":"and"},"looseTypeValidation":false,"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[500,400],"id":"dffe95bd-2fc5-4463-b831-28135a64ac8f","name":"Demande à Claude ?"},{"parameters":{"resource":"message","operation":"sendMessage","chatId":"={{ $json.chat_id }}","text":"={{ $json.text }}","replyMarkup":"none","additionalFields":{"appendAttribution":false}},"type":"n8n-nodes-base.telegram","typeVersion":1.2,"position":[2400,400],"id":"8e125b03-b72b-4a5b-babe-723c82203f4e","name":"Message texte","credentials":{"telegramApi