n.gouv.fr];\\r\\n\\tMIME_GOOD(-0.10)[multipart/mixed,multipart/alternative,text/plain,multipart/related];\\r\\n\\tR_DKIM_ALIGNED(-0.10)[strict];\\r\\n\\tR_DKIM_ALLOW(-0.10)[ac-grenoble.fr:s=msg-nat];\\r\\n\\tMID_RHS_MATCH_FROM(0.00)[];\\r\\n\\tRCVD_VIA_SMTP_AUTH(0.00)[];\\r\\n\\tMIME_TRACE(0.00)[0:+,1:+,2:+,3:+,4:~,5:~,6:~];\\r\\n\\tASN(0.00)[asn:2200, ipnet:193.54.0.0/15, country:FR];\\r\\n\\tRCVD_COUNT_THREE(0.00)[3];\\r\\n\\tDKIM_TRACE(0.00)[ac-grenoble.fr:+];\\r\\n\\tTO_DN_EQ_ADDR_ALL(0.00)[];\\r\\n\\tFROM_EQ_ENVFROM(0.00)[];\\r\\n\\tFROM_HAS_DN(0.00)[];\\r\\n\\tRCVD_TLS_LAST(0.00)[];\\r\\n\\tRCPT_COUNT_ZERO(0.00)[0];\\r\\n\\tTO_MATCH_ENVRCPT_ALL(0.00)[];\\r\\n\\tTO_DN_NONE(0.00)[];\\r\\n\\tHAS_ATTACHMENT(0.00)[]","X-Rspamd-Action: no action",["267"],"<span class=\\"mp_address_group\\"><span class=\\"mp_address_name\\">destinataires inconnus: </span>;</span>","\\"destinataires inconnus\\": ;",["268"],"<span class=\\"mp_address_group\\"><span class=\\"mp_address_name\\">Directeur D&#xE9;l&#xE9;gu&#xE9; L&#xE9;on Pavin</span> &lt;<a href=\\"mailto:ctx.0070009x@ac-grenoble.fr\\" class=\\"mp_address_email\\">ctx.0070009x@ac-grenoble.fr</a>&gt;</span>","image/jpeg","image","jpg","filesystem-v2","signature mail tel pro ddfpt.jpg","filesystem-v2:workflows/yBUJ2dGEjAusKSuD/executions/temp/binary_data/58a7b1b7-0c80-4002-952a-a9b1ea6b9dbd","64.7 kB","application/pdf","pdf","Réunion de rentrée Apprentissage 2026.pdf","filesystem-v2:workflows/yBUJ2dGEjAusKSuD/executions/temp/binary_data/944fc515-7cbf-40e8-a0c5-1f343349e50d","896 kB",["269"],"System: Tu es un assistant qui trie les emails professionnels d'une entreprise de menuiserie/ébénisterie (EBANISTA). Pour chaque email, réponds UNIQUEMENT en JSON avec cette structure exacte :\\n{\\n  \\"categorie\\": \\"offre_fournisseur\\" | \\"confirmation_commande\\" | \\"prospects\\" | \\"suivi_client\\" | \\"administratif\\" | \\"litige\\" | \\"facturation\\" | \\"spam\\",\\n  \\"urgent\\": true ou false,\\n  \\"resume\\": \\"résumé en 2-3 lignes maximum\\",\\n  \\"auto_envoi_possible\\": true ou false,\\n  \\"reponse_requise\\": true ou false\\n}\\n\\nCatégories (avec exemples) :\\n- offre_fournisseur : devis, propositions commerciales ou catalogues reçus d'un fournisseur. Ex : \\"Devis panneaux MDF - validité 30 jours\\"\\n- confirmation_commande : accusés de réception ou confirmations d'une commande déjà passée à un fournisseur. Ex : \\"Confirmation de votre commande n°4521\\"\\n- prospects : demandes d'information ou de devis de particuliers/entreprises intéressés par nos services. Ex : \\"Devis pour cuisine sur mesure\\"\\n- suivi_client : échanges avec des clients déjà engagés sur un projet en cours. Ex : \\"Où en est mon meuble ?\\"\\n- administratif : courriers officiels, banque, assurance, impôts, RH. Ex : \\"Relevé bancaire disponible\\"\\n- litige : réclamation, mise en demeure, mention d'avocat/tribunal, forte insatisfaction client. TOUJOURS urgent=true et auto_envoi_possible=false.\\n- facturation : factures reçues ou envoyées, relances de paiement. Ex : \\"Facture n°2026-045\\"\\n- spam : newsletters, publicités, phishing évident, démarchage commercial non sollicité sans rapport avec l'activité.\\n\\nRègles d'urgence :\\n- Ne pas se fier au mot \\"urgent\\" dans le sujet s'il n'est pas justifié par le contenu réel (une simple question commerciale n'est pas urgente même si le sujet dit \\"urgent\\").\\n- Est urgent : litige (toujours), délai serré explicite (\\"réponse avant demain\\"), problème bloquant sur un chantier en cours, client insatisfait qui réclame.\\n\\nRègles auto_envoi_possible :\\n- true UNIQUEMENT pour : accusé de réception simple sans action requise, confirmation de rdv déjà validée, confirmation_commande (accusé fournisseur).\\n- false pour tout le reste, en particulier : offre_fournisseur, devis, facture, litige, toute demande nécessitant une réponse personnalisée ou une décision métier.\\n\\nRègles reponse_requise :\\n- true si l'expéditeur attend une vraie réponse rédigée de l'entreprise : question, demande de devis ou de prix, demande de rendez-vous ou de disponibilité, relance, réclamation, proposition à accepter ou refuser.\\n- false pour : spam, notifications et mails automatiques (y compris les réponses automatiques d'absence), accusés de réception et confirmations sans question, factures et relevés sans question, newsletters, mails reçus seulement en copie pour information.\\n\\nLe résumé doit être factuel et concis, sans reformuler tout l'email.\\nHuman: Voici un email à analyser :\\nExpéditeur : \\"Directeur Délégué Léon Pavin\\" <ctx.0070009x@ac-grenoble.fr>\\nSujet : Support réunion apprentissage Lycée Léon PAVIN pour BTS ERA\\nContenu : Bonjour\\n\\nVeuillez trouver ci-joint le support du GRETA concernant l'apprentissage de nos étudiants en BTS Étude et Réalisation d'Agencement.\\n\\nCes informations ont été données à nos jeunes de 1ère année et aux tuteurs présents lors de la réunion du vendredi 9 octobre.\\n\\n\\nPour information, nous rencontrons actuellement des difficultés concernant le financement de notre formation BTS en apprentissage. À court terme, il existe un risque réel de voir disparaître cette offre de formation en Ardèche au sein de notre établissement.\\nCette situation critique est liée au fait que nos deux années de formation se déroulent en alternance. Les heures de formation sont entièrement prises en charge et supportées par le GRETA, mais elles ne sont pas compensées à la hauteur par le Niveau de Prise En Charge (NPEC) du BTS ERA versé par l'OPCO.\\nNotre formation est reconnue pour sa qualité et ses enseignements répondent parfaitement aux besoins de votre profession. C'est pourquoi nous pensons qu'il est primordial de maintenir cette offre de formation sur notre secteur géographique.\\nNous vous solliciterons certainement très prochainement pour obtenir votre soutien officiel. D'ici là, vous pouvez déjà relayer cette alerte et en discuter avec vos organismes professionnels ou vos chambres consulaires.\\nD'avance merci pour votre implication dans la formation des jeunes.\\nCordialement\\n\\n-- \\n",{"lc":1,"type":"270","id":"271"},"claude-sonnet-4-6","https://api.anthropic.com",{},{"fetchOptions":"272"},{"lc":1,"type":"270","id":"273"},{"name":"274","group":"275"},{"address":"202","name":"203"},["276"],"secret",["277"],{},["277"],"destinataires inconnus",[],{"text":"195"},"ANTHROPIC_API_KEY"]	9ae720d1-6695-40df-bb06-2ffc14b6dde8
473	{"id":"n443xVZ8J3tVez1B","name":"Tri mails - comptabilite","nodes":[{"parameters":{"mailbox":"INBOX","postProcessAction":"nothing","format":"resolved","dataPropertyAttachmentsPrefixName":"attachment_","options":{"customEmailConfig":"[\\"UNSEEN\\", [\\"SINCE\\", \\"Oct 9, 2026\\"]]"}},"type":"n8n-nodes-base.emailReadImap","typeVersion":2.2,"position":[0,0],"id":"4acf197b-93b5-4ffa-894d-e8cf9068550e","name":"Email Trigger (IMAP)","credentials":{"imap":{"id":"TkTrXXrbgNbUWRld","name":"IMAP - comptabilite@ebanista.fr"}}},{"parameters":{"notice":"","promptType":"define","text":"=Voici un email à analyser :\\nExpéditeur : {{ $json.from.text }}\\nSujet : {{ $json.subject }}\\nContenu : {{ $json.text }}\\n","hasOutputParser":false,"needsFallback":false,"messages":{"messageValues":[{"type":"SystemMessagePromptTemplate","message":"Tu es un assistant qui trie les emails professionnels d'une entreprise de menuiserie/ébénisterie (EBANISTA). Pour chaque email, réponds UNIQUEMENT en JSON avec cette structure exacte :\\n{\\n  \\"categorie\\": \\"offre_fournisseur\\" | \\"confirmation_commande\\" | \\"prospects\\" | \\"suivi_client\\" | \\"administratif\\" | \\"litige\\" | \\"facturation\\" | \\"spam\\",\\n  \\"urgent\\": true ou false,\\n  \\"resume\\": \\"résumé en 2-3 lignes maximum\\",\\n  \\"auto_envoi_possible\\": true ou false,\\n  \\"reponse_requise\\": true ou false\\n}\\n\\nCatégories (avec exemples) :\\n- offre_fournisseur : devis, propositions commerciales ou catalogues reçus d'un fournisseur. Ex : \\"Devis panneaux MDF - validité 30 jours\\"\\n- confirmation_commande : accusés de réception ou confirmations d'une commande déjà passée à un fournisseur. Ex : \\"Confirmation de votre commande n°4521\\"\\n- prospects : demandes d'information ou de devis de particuliers/entreprises intéressés par nos services. Ex : \\"Devis pour cuisine sur mesure\\"\\n- suivi_client : échanges avec des clients déjà engagés sur un projet en cours. Ex : \\"Où en est mon meuble ?\\"\\n- administratif : courriers officiels, banque, assurance, impôts, RH. Ex : \\"Relevé bancaire disponible\\"\\n- litige : réclamation, mise en demeure, mention d'avocat/tribunal, forte insatisfaction client. TOUJOURS urgent=true et auto_envoi_possible=false.\\n- facturation : factures reçues ou envoyées, relances de paiement. Ex : \\"Facture n°2026-045\\"\\n- spam : newsletters, publicités, phishing évident, démarchage commercial non sollicité sans rapport avec l'activité.\\n\\nRègles d'urgence :\\n- Ne pas se fier au mot \\"urgent\\" dans le sujet s'il n'est pas justifié par le contenu réel (une simple question commerciale n'est pas urgente même si le sujet dit \\"urgent\\").\\n- Est urgent : litige (toujours), délai serré explicite (\\"réponse avant demain\\"), problème bloquant sur un chantier en cours, client insatisfait qui réclame.\\n\\nRègles auto_envoi_possible :\\n- true UNIQUEMENT pour : accusé de réception simple sans action requise, confirmation de rdv déjà validée, confirmation_commande (accusé fournisseur).\\n- false pour tout le reste, en particulier : offre_fournisseur, devis, facture, litige, toute demande nécessitant une réponse personnalisée ou une décision métier.\\n\\nRègles reponse_requise :\\n- true si l'expéditeur attend une vraie réponse rédigée de l'entreprise : question, demande de devis ou de prix, demande de rendez-vous ou de disponibilité, relance, réclamation, proposition à accepter ou refuser.\\n- false pour : spam, notifications et mails automatiques (y compris les réponses automatiques d'absence), accusés de réception et confirmations sans question, factures et relevés sans question, newsletters, mails reçus seulement en copie pour information.\\n\\nLe résumé doit être factuel et concis, sans reformuler tout l'email."}]},"batching":{}},"type":"@n8n/n8n-nodes-langchain.chainLlm","typeVersion":1.9,"position":[608,0],"id":"0c6fe25a-11e3-4c7e-b5ae-efd8a3629137","name":"Basic LLM Chain"},{"parameters":{"notice":"","model":{"__rl":true,"mode":"list","value":"claude-sonnet-4-6","cachedResultName":"Claude Sonnet 4.6"},"options":{}},"type":"@n8n/n8n-nodes-langchain.lmChatAnthropic","typeVersion":1.5,"position":[992,0],"id":"9d47d40d-f929-4681-ab5c-711d775c9e1d","name":"Anthropic Chat Model","credentials":{"anthropicApi":{"id":"FRxZizEr7zCaHHZp","name":"Claude API"}}},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"const results = [];\\n\\nfor (const item of $input.all()) {\\n  const rawText = item.json.text;\\n  const match = rawText.match(/\\\\{[\\\\s\\\\S]*\\\\}/);\\n  const parsed = JSON.parse(match[0]);\\n  \\n  results.push({\\n    json: {\\n      categorie: parsed.categorie,\\n      urgent: parsed.urgent,\\n      resume: parsed.resume,\\n      auto_envoi_possible: parsed.auto_envoi_possible,\\n      reponse_requise: parsed.reponse_requise === true\\n    }\\n  });\\n}\\n\\nreturn results;\\n","notice":""},"type":"n8n-nodes-base.code","typeVersion":2,"position":[1120,144],"id":"10349273-435b-4320-b5fb-fbebf52de6a6","name":"Code in JavaScript"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"f22f7138-265f-46e1-8325-3ff0776b55a7","leftValue":"={{ $json.urgent }}","rightValue":"","operator":{"type":"boolean","operation":"true","singleValue":true}}],"combinator":"and"},"looseTypeValidation":false,"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[1344,144],"id":"0b6b1958-7db2-468c-bf33-935de9103024","name":"If"},{"parameters":{"resource":"message","operation":"sendMessage","chatId":"8848139246","text":"={{ (\\"🚨 Mail urgent reçu sur comptabilite@ebanista.fr\\\\n\\\\nDe : \\" + ($('Email Trigger (IMAP)').item.json.from.text) + \\"\\\\nCatégorie : \\" + ($json.categorie) + \\"\\\\n\\\\n\\" + ($json.resume) + \\"\\\\n\\").replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;') }}","replyMarkup":"none","additionalFields":{"appendAttribution":false,"parse_mode":"HTML"