{"parameters":{"dataTableId":{"__rl":true,"value":"IgT0r6Yg3ZtzMWNR","mode":"list","cachedResultName":"digest_mails","cachedResultUrl":"/projects/WBZOJkoq8ImSC8dI/datatables/IgT0r6Yg3ZtzMWNR"},"columns":{"mappingMode":"defineBelow","value":{"auto_envoye":"={{ false }}","expediteur":"={{ $('Email Trigger (IMAP)').item.json.from.text }}","categorie":"={{ $json.categorie }}","resume":"={{ $json.resume }}","date":"={{ $now.format('yyyy-MM-dd HH:mm') }}","boite":"comptabilite"},"matchingColumns":[],"schema":[{"id":"date","displayName":"date","required":false,"defaultMatch":false,"display":true,"type":"dateTime","readOnly":false,"removed":false},{"id":"expediteur","displayName":"expediteur","required":false,"defaultMatch":false,"display":true,"type":"string","readOnly":false,"removed":false},{"id":"categorie","displayName":"categorie","required":false,"defaultMatch":false,"display":true,"type":"string","readOnly":false,"removed":false},{"id":"resume","displayName":"resume","required":false,"defaultMatch":false,"display":true,"type":"string","readOnly":false,"removed":false},{"id":"auto_envoye","displayName":"auto_envoye","required":false,"defaultMatch":false,"display":true,"type":"boolean","readOnly":false,"removed":false},{"id":"boite","displayName":"boite","required":false,"defaultMatch":false,"display":true,"type":"string","readOnly":false,"removed":false}],"attemptToConvertTypes":false,"convertFieldsToString":false},"options":{}},"type":"n8n-nodes-base.dataTable","typeVersion":1.1,"position":[1568,240],"id":"122b45a3-88b0-46be-be02-8b79a661cf3f","name":"Insert row"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"f1a1b111-0000-4000-8000-00000000f001","leftValue":"={{ $json.categorie }}","rightValue":"spam","operator":{"type":"string","operation":"notEquals"}}],"combinator":"and"},"options":{}},"type":"n8n-nodes-base.filter","typeVersion":2.2,"position":[1344,0],"id":"f1a1b111-0000-4000-8000-000000000010","name":"Filtrer spam"},{"parameters":{"jsCode":"const folderMap = {\\n  offre_fournisseur: 'Tri-Offre fournisseur',\\n  confirmation_commande: 'Tri-Confirmation de commande',\\n  prospects: 'Tri-Prospects',\\n  suivi_client: 'Tri-SuiviClient',\\n  administratif: 'Tri-Administratif',\\n  litige: 'Tri-Litige',\\n  facturation: 'Tri-Facturation',\\n  spam: 'Spam'\\n};\\n\\n// Traite TOUS les mails d'un lot (plusieurs mails peuvent arriver en même temps)\\nreturn $input.all().map((entry, i) => {\\n  const item = entry.json;\\n  const targetFolder = folderMap[item.categorie] || 'Tri-Administratif';\\n  // Pas de réponse automatique sur cette boîte : seul le spam est marqué lu.\\n  const markAsRead = item.categorie === 'spam';\\n  return { json: { ...item, targetFolder, markAsRead }, pairedItem: { item: i } };\\n});"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[1344,288],"id":"f1a1b111-0000-4000-8000-000000000020","name":"Déterminer dossier cible"},{"parameters":{"authentication":"coreImapAccount","resource":"email","operation":"moveEmail","sourceMailbox":{"__rl":true,"mode":"path","value":"INBOX"},"emailUid":"={{ $('Email Trigger (IMAP)').item.json.attributes.uid }}","destinationMailbox":{"__rl":true,"mode":"path","value":"={{ $('Déterminer dossier cible').item.json.targetFolder }}"}},"type":"n8n-nodes-imap.imap","typeVersion":1,"position":[1568,288],"id":"f1a1b111-0000-4000-8000-000000000021","name":"Déplacer le mail","credentials":{"imap":{"id":"TkTrXXrbgNbUWRld","name":"IMAP - comptabilite@ebanista.fr"}}},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"f1a1b111-0000-4000-8000-00000000f003","leftValue":"={{ $json.markAsRead }}","rightValue":"","operator":{"type":"boolean","operation":"true","singleValue":true}}],"combinator":"and"},"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[1568,200],"id":"f1a1b111-0000-4000-8000-00000