22645138-d9d6-480e-8a5c-74802b29b2ad	BqxroOO9AP3RhIjx	Valentin Caufriez	2026-10-09 19:09:23.232+00	2026-10-09 19:09:23.232+00	[{"parameters":{"inputSource":"passthrough"},"type":"n8n-nodes-base.executeWorkflowTrigger","typeVersion":1.1,"position":[0,0],"id":"a1000000-0000-4000-8000-000000000001","name":"Entrée sous-workflow"},{"parameters":{"authentication":"imapThisNode","resource":"email","operation":"getEmailsList","mailboxPath":{"__rl":true,"mode":"path","value":"Sent"},"emailDateRange":{"since":"={{ $now.minus({ years: 1 }).toISO() }}"},"emailSearchFilters":{"to":"={{ $json.from_address || 'adresse-introuvable@invalid.invalid' }}"},"limit":40,"includeParts":["textContent"]},"type":"n8n-nodes-imap.imap","typeVersion":1,"position":[260,0],"id":"a1000000-0000-4000-8000-000000000002","name":"Retrouver mes réponses précédentes","alwaysOutputData":true,"onError":"continueRegularOutput","credentials":{"imapApi":{"id":"7D7EF7hYzLreslfS","name":"IMAP Move - v.caufriez@ebanista.fr"}}},{"parameters":{"jsCode":"// Assemble le prompt : mail reçu + historique des réponses précédentes à ce correspondant\\nconst src = $('Entrée sous-workflow').first().json;\\nconst found = $input.all().map(i => i.json).filter(j => j && j.envelope && !j.error);\\n\\nconst ownText = (t) => String(t || '').replace(/\\\\r/g, '')\\n  .split(/\\\\n(?:>|Le .{5,90} a écrit|De ?:|From:|-----Original|On .{5,90} wrote)/)[0].trim();\\n\\nconst history = found\\n  .map(j => ({ date: new Date(j.envelope.date || 0), subject: j.envelope.subject || '', text: ownText(j.textContent) }))\\n  .filter(h => h.text.length >= 30)\\n  .sort((a, b) => b.date - a.date)\\n  .slice(0, 3)\\n  .map((h, n) => `--- Échange ${n + 1} (${h.date.toISOString().slice(0, 10)}, objet : ${h.subject}) ---\\\\n${h.text.slice(0, 700)}`)\\n  .join('\\\\n\\\\n');\\n\\nconst body = String(src.text || '').trim().slice(0, 4000);\\nconst prompt = [\\n  'MAIL REÇU',\\n  `De : ${src.from_name ? src.from_name + ' ' : ''}<${src.from_address}>`,\\n  `Objet : ${src.subject}`,\\n  `Date : ${src.date}`,\\n  `Résumé (assistant de tri) : ${src.resume || ''}`,\\n  '',\\n  'Contenu :',\\n  body || '(message sans texte)',\\n  '',\\n  'HISTORIQUE : tes dernières réponses à cet interlocuteur (de la plus récente à la plus ancienne)',\\n  history || \\"(aucun échange précédent trouvé : vouvoie par défaut)\\",\\n  '',\\n  'Rédige le brouillon de réponse.'\\n].join('\\\\n');\\n\\nreturn [{ json: { prompt, historyCount: history ? history.split('--- Échange ').length - 1 : 0 } }];\\n"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[520,0],"id":"a1000000-0000-4000-8000-000000000003","name":"Assembler le contexte"},{"parameters":{"promptType":"define","text":"={{ $json.prompt }}","messages":{"messageValues":[{"type":"SystemMessagePromptTemplate","message":"Tu rédiges des BROUILLONS de réponses d'e-mails pour Valentin Caufriez, gérant d'EBANISTA (menuiserie / ébénisterie sur mesure). Il relira et modifiera chaque brouillon avant de l'envoyer : tu écris à sa place, dans son style.\\n\\nRéponds UNIQUEMENT avec le corps du message : pas d'objet, pas de commentaire, pas de guillemets, pas de balises.\\n\\nSON STYLE (tiré de ses mails envoyés) :\\n- Court et direct : le plus souvent 3 à 8 lignes, paragraphes très courts, aucune formule ampoulée ni phrase de remplissage.\\n- Tutoiement (\\"Salut Prénom,\\") avec les fournisseurs et contacts qu'il connaît bien ; vouvoiement (\\"Bonjour,\\", \\"Bonjour Monsieur,\\") avec les inconnus, les clients et les interlocuteurs formels.\\n- Choix tu / vous : si l'historique de ses échanges avec cette personne montre le tutoiement, tutoie ; s'il montre le vouvoiement, vouvoie. Sans historique, vouvoie, avec \\"Bonjour,\\" (ajoute le prénom ou \\"Monsieur\\"/\\"Madame\\" seulement si tu en es sûr).\\n- Remerciements simples : \\"Merci pour votre retour\\", \\"Je te remercie,\\".\\n- Commandes et demandes de prix : liste à tirets, une quantité ou une référence par ligne, par exemple \\"- 3 x 730/2040 PD\\".\\n- Fin du message : \\"Cordialement,\\" presque toujours ; avec les interlocuteurs proches, \\"À bientôt,\\" ou \\"Bien à toi,\\". Signature sur la ligne suivante : \\"Valentin\\" (proche) ou \\"Valentin Caufriez\\" (formel).\\n- Il va droit au but et confirme clairement ce qui est décidé, sans excès de politesse.\\n\\nRÈGLES STRICTES :\\n- N'invente JAMAIS un prix, un délai, une disponibilité, une date, une quantité, une référence, une dimension ni un engagement. Si une information nécessaire manque, écris [À COMPLÉTER : ce qu'il faut préciser] à l'endroit voulu.\\n- Ne confirme pas de rendez-vous, de commande ni de devis de ta propre initiative. Écris plutôt la réponse la plus prudente (accuser réception, demander une précision, dire qu'il revient vers l'interlocuteur) et laisse [À COMPLÉTER] pour la décision.\\n- Les DÉCISIONS de Valentin ne sont jamais à ta charge : accepter ou refuser une offre, valider un devis, maintenir, passer ou annuler une commande, fixer une date ou un prix. N'écris jamais \\"oui\\", \\"c'est d'accord\\", \\"je confirme\\" ou \\"je maintiens\\" à sa place. Écris [À COMPLÉTER : décision à prendre (ce qu'il faut trancher)] ou une réponse neutre.\\n- N'ajoute AUCUNE précision (références, sens, finition, dimensions, quantités) qui n'est pas dans le mail reçu, même si elle apparaît dans l'historique : l'historique ne sert qu'à choisir le ton (tu / vous), la salutation et la formule de fin.\\n- Réponds à toutes les questions posées dans le mail reçu, point par point si nécessaire.\\n- Pour une réclamation ou un litige : ton calme, factuel et ferme, sans reconnaître de faute ni promettre de geste commercial ; laisse [À COMPLÉTER] pour les décisions.\\n- Écris en français, sauf si l'interlocuteur écrit dans une autre langue : réponds alors dans sa langue.\\n- Ne cite pas l'historique et ne recopie pas le mail reçu."}]},"batching":{}},"type":"@n8n/n8n-nodes-langchain.chainLlm","typeVersion":1.9,"position":[780,0],"id":"a1000000-0000-4000-8000-000000000004","name":"Rédiger le brouillon"},{"parameters":{"model":{"__rl":true,"mode":"list","value":"claude-sonnet-4-6","cachedResultName":"Claude Sonnet 4.6"},"options":{"temperature":0.4}},"type":"@n8n/n8n-nodes-langchain.lmChatAnthropic","typeVersion":1.5,"position":[820,220],"id":"a1000000-0000-4000-8000-000000000005","name":"Modèle Claude (brouillon)","credentials":{"anthropicApi":{"id":"FRxZizEr7zCaHHZp","name":"Claude API"}}},{"parameters":{"jsCode":"// Compose un e-mail RFC822 (réponse) à enregistrer dans le dossier Brouillons\\nconst src = $('Entrée sous-workflow').first().json;\\nconst draft = String($input.first().json.text || '').trim();\\nif (!draft) throw new Error('Brouillon vide renvoyé par le modèle');\\n\\nconst MY = { name: 'Valentin Caufriez', addr: 'v.caufriez@ebanista.fr' };\\nconst CRLF = '\\\\r\\\\n';\\nconst b64 = (s) => Buffer.from(s, 'utf8').toString('base64');\\nconst isAscii = (s) => /^[\\\\x20-\\\\x7e]*$/.test(s);\\n\\n// en-tête non ASCII -> mots encodés (RFC 2047), découpés en petits morceaux\\nconst encodeHeader = (s) => {\\n  if (isAscii(s)) return s;\\n  const chars = Array.from(s), parts = [];\\n  for (let i = 0; i < chars.length; i += 10) parts.push(`=?UTF-8?B?${b64(chars.slice(i, i + 10).join(''))}?=`);\\n  return parts.join(CRLF + ' ');\\n};\\nconst displayName = (name) => {\\n  if (!name) return '';\\n  // nom non ASCII : un seul mot encodé (le découper en plusieurs mots encodés le coupe à l'affichage)\\n  if (!isAscii(name)) return `=?UTF-8?B?${b64(name)}?=`;\\n  return /[^\\\\w .'-]/.test(name) ? `\\"${name.replace(/([\\"\\\\\\\\])/g, '\\\\\\\\$1')}\\"` : name;\\n};\\n\\nlet subject = String(src.subject || '').trim();\\nwhile (/^(re|ré)\\\\s*:\\\\s*/i.test(subject)) subject = subject.replace(/^(re|ré)\\\\s*:\\\\s*/i, '');\\nsubject = 'Re: ' + subject;\\n\\nconst origId = src.message_id ? (String(src.message_id).startsWith('<') ? src.message_id : `<${src.message_id}>`) : '';\\nconst when = src.date ? new Date(src.date).toLocaleString('fr-FR', { timeZone: 'Europe/Paris', dateStyle: 'long', timeStyle: 'short' }) : '';\\nconst who = (src.from_name ? src.from_name + ' ' : '') + `<${src.from_address}>`;\\nconst quoted = String(src.text || '').replace(/\\\\r/g, '').trim().slice(0, 3000).split('\\\\n').map(l => '> ' + l).join('\\\\n');\\nconst text = `${draft}\\\\n\\\\n\\\\nLe ${when}, ${who} a écrit :\\\\n${quoted}\\\\n`;\\n\\nconst headers = [\\n  `From: ${displayName(MY.name)} <${MY.addr}>`,\\n  `To: ${src.from_name ? displayName(src.from_name) + ' ' : ''}<${src.from_address}>`,\\n  `Subject: ${encodeHeader(subject)}`,\\n  `Date: ${new Date().toUTCString().replace('GMT', '+0000')}`,\\n  `Message-ID: <draft-${Date.now()}-${Math.random().toString(36).slice(2, 10)}@ebanista.fr>`,\\n  ...(origId ? [`In-Reply-To: ${origId}`, `References: ${origId}`] : []),\\n  'MIME-Version: 1.0',\\n  'Content-Type: text/plain; charset=UTF-8',\\n  'Content-Transfer-Encoding: base64',\\n];\\nconst bodyB64 = b64(text.replace(/\\\\n/g, CRLF)).replace(/(.{76})/g, '$1' + CRLF);\\n\\nreturn [{ json: { rfc822: headers.join(CRLF) + CRLF + CRLF + bodyB64 + CRLF, subject, draftPreview: draft } }];\\n"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[1100,0],"id":"a1000000-0000-4000-8000-000000000006","name":"Composer le brouillon"},{"parameters":{"authentication":"imapThisNode","resource":"email","operation":"createDraft","destinationMailbox":{"__rl":true,"mode":"path","value":"Drafts"},"inputFormat":"rfc822","rfc822":"={{ $json.rfc822 }}"},"type":"n8n-nodes-imap.imap","typeVersion":1,"position":[1360,0],"id":"a1000000-0000-4000-8000-000000000007","name":"Enregistrer dans Brouillons","credentials":{"imapApi":{"id":"7D7EF7hYzLreslfS","name":"IMAP Move - v.caufriez@ebanista.fr"}}}]	{"Entrée sous-workflow":{"main":[[{"node":"Retrouver mes réponses précédentes","type":"main","index":0}]]},"Retrouver mes réponses précédentes":{"main":[[{"node":"Assembler le contexte","type":"main","index":0}]]},"Assembler le contexte":{"main":[[{"node":"Rédiger le brouillon","type":"main","index":0}]]},"Modèle Claude (brouillon)":{"ai_languageModel":[[{"node":"Rédiger le brouillon","type":"ai_languageModel","index":0}]]},"Rédiger le brouillon":{"main":[[{"node":"Composer le brouillon","type":"main","index":0}]]},"Composer le brouillon":{"main":[[{"node":"Enregistrer dans Brouillons","type":"main","index":0}]]}}	\N	f	\N	[]
8c2840da-4b6b-4427-8891-2e9be062510c	lfynCIkeDPS6hIXu	Valentin Caufriez	2026-10-09 20:36:46.833+00	2026-10-09 20:36:46.833+00	[{"parameters":{"rule":{"interval":[{"field":"cronExpression","expression":"0 7 * * *"}]}},"type":"n8n-nodes-base.scheduleTrigger","typeVersion":1.2,"position":[0,0],"id":"d1a1b111-0000-4000-8000-000000000001","name":"Schedule Trigger 7h"},{"parameters":{"method":"GET","url":"http://localhost:5678/api/v1/data-tables/IgT0r6Yg3ZtzMWNR/rows","authentication":"genericCredentialType","genericAuthType":"httpHeaderAuth","sendQuery":true,"queryParameters":{"parameters":[{"name":"limit","value":"250"}]},"options":{}},"type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[224,0],"id":"d1a1b111-0000-4000-8000-000000000002","name":"Get digest_mails rows","credentials":{"httpHeaderAuth":{"id":"Lfuh7XFXewkeDjJe","name":"n8n API Key (interne)"}}},{"parameters":{"jsCode":"const rows = $input.first().json.data || [];\\n\\nconst LIMIT = 3800; // limite Telegram : 4096 caractères par message\\nconst LABELS = { 'v.caufriez': 'v.caufriez@ebanista.fr', 'contact': 'contact@ebanista.fr', 'comptabilite': 'comptabilite@ebanista.fr' };\\nconst ORDER = ['v.caufriez', 'contact', 'comptabilite'];\\n\\nif (rows.length === 0) {\\n  return [{ json: { text: \\"📋 Digest quotidien EBANISTA\\\\n\\\\nAucun mail à traiter aujourd'hui.\\", count: 0 } }];\\n}\\n\\n// regroupement par boîte (les anciennes lignes sans boîte viennent de v.caufriez)\\nconst groups = {};\\nfor (const r of rows) {\\n  const box = r.boite || 'v.caufriez';\\n  (groups[box] = groups[box] || []).push(r);\\n}\\nconst boxes = [...ORDER.filter(b => groups[b]), ...Object.keys(groups).filter(b => !ORDER.includes(b))];\\n\\n// un bloc de texte par boîte, puis découpage en messages de taille raisonnable\\nconst blocks = [];\\nfor (const box of boxes) {\\n  const list = groups[box];\\n  blocks.push(`📥 ${LABELS[box] || box} (${list.length})`);\\n  for (const r of list) {\\n    blocks.push(`• [${r.categorie}] ${r.expediteur}\\\\n  ${r.resume}`);\\n  }\\n}\\n\\nconst header = `📋 Digest quotidien EBANISTA — ${rows.length} mail(s)`;\\nconst chunks = [];\\nlet current = header;\\nfor (const b of blocks) {\\n  const next = current + '\\\\n\\\\n' + b;\\n  if (next.length > LIMIT && current !== header) {\\n    chunks.push(current);\\n    current = '(suite)\\\\n\\\\n' + b;\\n  } else {\\n    current = next;\\n  }\\n}\\nchunks.push(current);\\n\\nreturn chunks.map(text => ({ json: { text, count: rows.length } }));\\n"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[448,0],"id":"d1a1b111-0000-4000-8000-000000000003","name":"Build digest text"},{"parameters":{"chatId":"8848139246","text":"={{ (($json.text)).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;') }}","additionalFields":{"appendAttribution":false,"parse_mode":"HTML"}},"type":"n8n-nodes-base.telegram","typeVersion":1.2,"position":[672,0],"id":"d1a1b111-0000-4000-8000-000000000004","name":"Send digest to Telegram","credentials":{"telegramApi":{"id":"duvmoy6UkxnbnBdr","name":"Ebanista Mails"}},"webhookId":"363c01d7-51fe-4fad-9eaa-5b88407a022d"},{"parameters":{"method":"DELETE","url":"http://localhost:5678/api/v1/data-tables/IgT0r6Yg3ZtzMWNR/rows/clear","authentication":"genericCredentialType","genericAuthType":"httpHeaderAuth","options":{}},"type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[896,0],"id":"d1a1b111-0000-4000-8000-000000000005","name":"Clear digest_mails table","credentials":{"httpHeaderAuth":{"id":"Lfuh7XFXewkeDjJe","name":"n8n API Key (interne)"}}}]	{"Schedule Trigger 7h":{"main":[[{"node":"Get digest_mails rows","type":"main","index":0}]]},"Get digest_mails rows":{"main":[[{"node":"Build digest text","type":"main","index":0}]]},"Build digest text":{"main":[[{"node":"Send digest to Telegram","type":"main","index":0}]]},"Send digest to Telegram":{"main":[[{"node":"Clear digest_mails table","type":"main","index":0}]]}}	\N	f	\N	[]
5c29d16c-3f1a-4e34-9ed6-2e0f2c8c4ebc	FqdcdqnhtYVRYTz6	Valentin Caufriez	2026-10-09 20:36:47.704+00	2026-10-09 20:36:47.704+00	[{"parameters":{"format":"resolved","options":{},"postProcessAction":"nothing"},"type":"n8n-nodes-base.emailReadImap","typeVersion":2.2,"position":[0,0],"id":"4acf197b-93b5-4ffa-894d-e8cf9068550e","name":"Email Trigger (IMAP)","credentials":{"imap":{"id":"wVKdbE1JQnIB1kzf","name":"IMAP - v.caufriez@ebanista.fr"}}},{"parameters":{"promptType":"define","text":"=Voici un email à analyser :\\nExpéditeur : {{ $json.from.text }}\\nSujet : {{ $json.subject }}\\nContenu : {{ $json.text }}\\n","messages":{"messageValues":[{"message":"Tu es un assistant qui trie les emails professionnels d'une entreprise de menuiserie/ébénisterie (EBANISTA). Pour chaque email, réponds UNIQUEMENT en JSON avec cette structure exacte :\\n{\\n  \\"categorie\\": \\"offre_fournisseur\\" | \\"confirmation_commande\\" | \\"prospects\\" | \\"suivi_client\\" | \\"administratif\\" | \\"litige\\" | \\"facturation\\" | \\"spam\\",\\n  \\"urgent\\": true ou false,\\n  \\"resume\\": \\"résumé en 2-3 lignes maximum\\",\\n  \\"auto_envoi_possible\\": true ou false,\\n  \\"reponse_requise\\": true ou false\\n}\\n\\nCatégories (avec exemples) :\\n- offre_fournisseur : devis, propositions commerciales ou catalogues reçus d'un fournisseur. Ex : \\"Devis panneaux MDF - validité 30 jours\\"\\n- confirmation_commande : accusés de réception ou confirmations d'une commande déjà passée à un fournisseur. Ex : \\"Confirmation de votre commande n°4521\\"\\n- prospects : demandes d'information ou de devis de particuliers/entreprises intéressés par nos services. Ex : \\"Devis pour cuisine sur mesure\\"\\n- suivi_client : échanges avec des clients déjà engagés sur un projet en cours. Ex : \\"Où en est mon meuble ?\\"\\n- administratif : courriers officiels, banque, assurance, impôts, RH. Ex : \\"Relevé bancaire disponible\\"\\n- litige : réclamation, mise en demeure, mention d'avocat/tribunal, forte insatisfaction client. TOUJOURS urgent=true et auto_envoi_possible=false.\\n- facturation : factures reçues ou envoyées, relances de paiement. Ex : \\"Facture n°2026-045\\"\\n- spam : newsletters, publicités, phishing évident, démarchage commercial non sollicité sans rapport avec l'activité.\\n\\nRègles d'urgence :\\n- Ne pas se fier au mot \\"urgent\\" dans le sujet s'il n'est pas justifié par le contenu réel (une simple question commerciale n'est pas urgente même si le sujet dit \\"urgent\\").\\n- Est urgent : litige (toujours), délai serré explicite (\\"réponse avant demain\\"), problème bloquant sur un chantier en cours, client insatisfait qui réclame.\\n\\nRègles auto_envoi_possible :\\n- true UNIQUEMENT pour : accusé de réception simple sans action requise, confirmation de rdv déjà validée, confirmation_commande (accusé fournisseur).\\n- false pour tout le reste, en particulier : offre_fournisseur, devis, facture, litige, toute demande nécessitant une réponse personnalisée ou une décision métier.\\n\\nRègles reponse_requise :\\n- true si l'expéditeur attend une vraie réponse rédigée de Valentin : question, demande de devis ou de prix, demande de rendez-vous ou de disponibilité, relance, réclamation, proposition à accepter ou refuser.\\n- false pour : spam, notifications et mails automatiques (y compris les réponses automatiques d'absence), accusés de réception et confirmations sans question, factures et relevés sans question, newsletters, mails reçus seulement en copie pour information.\\n\\nLe résumé doit être factuel et concis, sans reformuler tout l'email."}]},"batching":{}},"type":"@n8n/n8n-nodes-langchain.chainLlm","typeVersion":1.9,"position":[608,0],"id":"0c6fe25a-11e3-4c7e-b5ae-efd8a3629137","name":"Basic LLM Chain"},{"parameters":{"model":{"__rl":true,"mode":"list","value":"claude-sonnet-4-6","cachedResultName":"Claude Sonnet 4.6"},"options":{}},"type":"@n8n/n8n-nodes-langchain.lmChatAnthropic","typeVersion":1.5,"position":[992,0],"id":"9d47d40d-f929-4681-ab5c-711d775c9e1d","name":"Anthropic Chat Model","credentials":{"anthropicApi":{"id":"FRxZizEr7zCaHHZp","name":"Claude API"}}},{"parameters":{"jsCode":"const results = [];\\n\\nfor (const item of $input.all()) {\\n  const rawText = item.json.text;\\n  const match = rawText.match(/\\\\{[\\\\s\\\\S]*\\\\}/);\\n  const parsed = JSON.parse(match[0]);\\n  \\n  results.push({\\n    json: {\\n      categorie: parsed.categorie,\\n      urgent: parsed.urgent,\\n      resume: parsed.resume,\\n      auto_envoi_possible: parsed.auto_envoi_possible,\\n      reponse_requise: parsed.reponse_requise === true\\n    }\\n  });\\n}\\n\\nreturn results;\\n"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[1120,144],"id":"10349273-435b-4320-b5fb-fbebf52de6a6","name":"Code in JavaScript"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"f22f7138-265f-46e1-8325-3ff0776b55a7","leftValue":"={{ $json.urgent }}","rightValue":"","operator":{"type":"boolean","operation":"true","singleValue":true}}],"combinator":"and"},"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.3,"position":[1344,144],"id":"0b6b1958-7db2-468c-bf33-935de9103024","name":"If"},{"parameters":{"chatId":"8848139246","text":"={{ (\\"🚨 Mail urgent reçu\\\\n\\\\nDe : \\" + ($('Email Trigger (IMAP)').item.json.from.text) + \\"\\\\nCatégorie : \\" + ($json.categorie) + \\"\\\\n\\\\n\\" + ($json.resume) + \\"\\\\n\\").replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;') }}","additionalFields":{"appendAttribution":false,"parse_mode":"HTML"},"replyMarkup":"inlineKeyboard","inlineKeyboard":{"rows":[{"row":{"buttons":[{"text":"↩️ Répondre","additionalFields":{"callback_data":"={{ 'rep:v:' + $('Email Trigger (IMAP)').item.json.attributes.uid }}"}}]}}]}},"type":"n8n-nodes-base.telegram","typeVersion":1.2,"position":[1568,48],"id":"a00d2675-2c89-4e0f-b077-76de969ad947","name":"Send a text message","webhookId":"98c72095-6cd